L["1 icon in it is set to not displayed in your Cooldown Manager, so it stays out."] = "1 Symbol darin ist in deinem Abklingzeitmanager auf „Nicht angezeigt“ gesetzt und bleibt daher draußen."
L["1 kind"] = "1 Art"
L["1 layout hidden here. Show it"] = "1 Layout hier ausgeblendet. Anzeigen"
L["1 match"] = "1 Treffer"
L["1 of them is in Arc Auras already: importing again adds a second copy."] = "1 davon ist schon in Arc Auras: ein erneuter Import fügt eine zweite Kopie hinzu."
L["1 profile"] = "1 Profil"
L["1 reminder"] = "1 Erinnerung"
L["1 rule"] = "1 Regel"
L["1 setting differs from the group; a cyan bar marks it."] = "1 Einstellung weicht von der Gruppe ab; ein cyanfarbener Balken markiert sie."
L["1 texture"] = "1 Textur"
L["3 to 10, spot 1 at the top. Fewer spots keep what sat on the others: it comes back with more."] = "3 bis 10, Platz 1 oben. Bei weniger Plätzen bleibt erhalten, was auf den anderen lag: Mit mehr Plätzen ist es wieder da."
L["30 is a debuff's pandemic window. Needs no length."] = "30 ist das Pandemie-Fenster eines Schwächungszaubers. Braucht keine Länge."
L[": matches again ("] = ": matches again ("
L["A 2.6 second timer that runs out and starts again."] = "Ein 2,6-Sekunden-Timer, der abläuft und neu startet."
L["A Cooldown Manager icon"] = "Ein Symbol des Abklingzeitmanagers"
L["A Custom Icon or Bar"] = "Eigenes Symbol oder Balken"
L["A Custom Icon or Bar's value"] = "Der Wert eines eigenen Symbols oder Balkens"
L["A Dynamic aura group only tracks you, your pet and your target."] = "Eine dynamische Aura-Gruppe verfolgt nur dich, deinen Begleiter und dein Ziel."
L["A Dynamic group only tracks you, your pet and your target: turn its Dynamic off."] = "Eine dynamische Gruppe verfolgt nur dich, deinen Begleiter und dein Ziel: Schalte ihre Dynamik aus."
L["A blank layout. Add your own groups, icons and bars."] = "Ein leeres Layout. Füge eigene Gruppen, Symbole und Balken hinzu."
L["A buff or debuff as an icon; several IDs can light one icon."] = "Ein Stärkungseffekt oder Schwächungszauber als Symbol; mehrere IDs können ein Symbol aktivieren."
L["A cast that finishes, one that is interrupted, then a channel."] = "Ein Zauber, der durchläuft, einer, der unterbrochen wird, dann ein Kanalisieren."
L["A cast while it runs: start it over, add the seconds to what is left, leave it running, or end it."] = "Ein erneutes Wirken, während es läuft: neu starten, die Sekunden zur Restzeit addieren, weiterlaufen lassen oder beenden."
L["A charge left and another coming back, over and over: the Recharging look, with its opacity, grey out, tint and glow."] = "Eine Aufladung ist weg und eine weitere kommt zurück, immer wieder: die Optik „Lädt auf“ mit Transparenz, Ausgrauen, Tönung und Leuchten."
L["A condition turns off"] = "Eine Bedingung schaltet sich aus"
L["A condition turns on"] = "Eine Bedingung schaltet sich ein"
L["A cooldown ID names a Cooldown Manager icon, so it stays at its own spot."] = "Eine Abklingzeit-ID bezeichnet ein Symbol des Abklingzeitmanagers und bleibt daher an seinem eigenen Platz."
L["A cooldown ID names a Cooldown Manager icon."] = "Eine Abklingzeit-ID bezeichnet ein Symbol des Abklingzeitmanagers."
L["A deck bar fills as the deck is drawn, with a mark for each proc."] = "Ein Deck-Balken füllt sich, während das Deck gezogen wird, mit einer Markierung für jeden Proc."
L["A deck of 100 stacks holding 2 Tempest procs."] = "Ein Deck aus 100 Stapeln mit 2 Sturmgewitter-Procs."
L["A deck of 250 stacks holding 5 Storm Unleashed procs."] = "Ein Deck aus 250 Stapeln mit 5 Procs von Entfesselter Sturm."
L["A deck of 333 Maelstrom holding 2 Tempest procs."] = "Ein Deck aus 333 Mahlstrom mit 2 Sturmgewitter-Procs."
L["A deck of 333 stacks holding 2 Ascendance procs."] = "Ein Deck aus 333 Stapeln mit 2 Aszendenz-Procs."
L["A deck of 600 Maelstrom Weapon stacks holding 3 Doom Winds procs."] = "Ein Deck aus 600 Stapeln von Waffe des Mahlstroms mit 3 Schicksalswinde-Procs."
L["A dim dark line along the edge, under the moving lines."] = "Eine schwache dunkle Linie am Rand, unter den bewegten Linien."
L["A female voice"] = "Eine weibliche Stimme"
L["A fill, like a bar"] = "Eine Füllung wie bei einem Balken"
L["A glow around the bar, with a trigger of its own. Works in combat."] = "Ein Leuchten um den Balken mit eigenem Auslöser. Funktioniert im Kampf."
L["A grid of small tiles showing the art and the name. Click a tile to edit it. Hover it for its details, Edit and Delete."] = "Ein Raster kleiner Kacheln mit Bild und Name. Klicke eine Kachel, um sie zu bearbeiten. Fahre darüber für Details, Bearbeiten und Löschen."
L["A group needs at least one column."] = "Eine Gruppe braucht mindestens eine Spalte."
L["A group needs at least one row."] = "Eine Gruppe braucht mindestens eine Zeile."
L["A layout for 1 class"] = "Ein Layout für 1 Klasse"
L["A layout pack you use has a newer version."] = "Ein von dir genutztes Layout-Paket hat eine neuere Version."
L["A look of its own under a time left"] = "Eine eigene Optik unterhalb einer Restzeit"
L["A look under a time left"] = "Eine Optik unterhalb einer Restzeit"
L["A male voice"] = "Eine männliche Stimme"
L["A mark where each spell's cost is met. It shows with Tick marks on (Appearance > Ticks)."] = "Eine Markierung dort, wo die Kosten des jeweiligen Zaubers gedeckt sind. Sie erscheint bei aktivierten Markierungen (Darstellung > Markierungen)."
L["A mark where your next spell can be queued: press it past the mark and it goes off as soon as this cast ends."] = "Eine Markierung, ab der dein nächster Zauber vorgemerkt werden kann: Drückst du ihn hinter der Markierung, wird er ausgelöst, sobald dieses Zaubern endet."
L["A missing aura"] = "Eine fehlende Aura"
L["A name, version, link and notes for your pack. Whoever imports the string sees them first."] = "Ein Name, eine Version, ein Link und Notizen für dein Paket. Wer den String importiert, sieht sie zuerst."
L["A named frame"] = "Ein benannter Frame"
L["A nameplate: not offered"] = "Eine Namensplakette: nicht angeboten"
L["A newer version is out: click to update your copy"] = "Eine neuere Version ist erschienen: Klicke, um deine Kopie zu aktualisieren"
L["A newer version of this layout is out. Updates the layout you made from it; your own sizes and positions stay."] = "Eine neuere Version dieses Layouts ist erschienen. Aktualisiert das daraus erstellte Layout; deine eigenen Größen und Positionen bleiben."
L["A percent of the bar, or power with In power units on."] = "Ein Prozentwert des Balkens, oder Ressource bei aktivierter Option „In Ressourceneinheiten“."
L["A picture of your own: its FileDataID, or its path such as Interface/AddOns/MyMedia/glow. Enter applies it; empty = pick one above."] = "Ein eigenes Bild: seine FileDataID oder sein Pfad, z. B. Interface/AddOns/MyMedia/glow. Enter übernimmt es; leer = oben eines wählen."
L["A picture that follows an aura, a cooldown, your power, health or triggers."] = "Ein Bild, das einer Aura, einer Abklingzeit, deiner Ressource, Gesundheit oder Auslösern folgt."
L["A power bar; Automatic follows the power you are using."] = "Ein Ressourcenbalken; Automatisch folgt der Ressource, die du gerade benutzt."
L["A proc glow ended"] = "Ein Proc-Leuchten endete"
L["A proc glow started"] = "Ein Proc-Leuchten begann"
L["A proc shows it at full opacity"] = "Ein Proc zeigt es voll sichtbar"
L["A quarter turn: the bar becomes tall and thin, and its icon, texture and gradient turn with it."] = "Eine Vierteldrehung: Der Balken wird hoch und schmal, und sein Symbol, seine Textur und sein Verlauf drehen sich mit."
L["A rank: only that one, such as a cheaper rank you queue to save mana."] = "Ein Rang: nur dieser, z. B. ein günstigerer Rang, den du vormerkst, um Mana zu sparen."
L["A reactive ability lit up"] = "Eine reaktive Fähigkeit leuchtet auf"
L["A reminder exported on its own joins this group. A group keeps one reminder per spell, item or weapon hand, so duplicates stay out."] = "Eine einzeln exportierte Erinnerung kommt in diese Gruppe. Eine Gruppe behält pro Zauber, Gegenstand oder Waffenhand eine Erinnerung, daher gibt es keine Duplikate."
L["A returning icon"] = "Ein wiederkehrendes Symbol"
L["A ring of your spells and items: hold its key, point at one and let go to cast it."] = "Ein Ring aus deinen Zaubern und Gegenständen: Halte seine Taste, zeige auf einen Eintrag und lass los, um ihn auszulösen."
L["A ring, like a cooldown"] = "Ein Ring wie bei einer Abklingzeit"
L["A set duration"] = "Eine feste Dauer"
L["A share of the time"] = "Ein Anteil der Zeit"
L["A short flash"] = "Ein kurzes Aufblitzen"
L["A short word, like %s"] = "Ein kurzes Wort, z. B. %s"
L["A short word, like C"] = "Ein kurzes Wort, z. B. C"
L["A short word, like D"] = "Ein kurzes Wort, z. B. D"
L["A short word, like M"] = "Ein kurzes Wort, z. B. M"
L["A short word, like N"] = "Ein kurzes Wort, z. B. N"
L["A short word, like P"] = "Ein kurzes Wort, z. B. P"
L["A skin made from the default look. A bar's Skin dropdown makes one from that bar's look."] = "Ein Skin aus der Standardoptik. Das Skin-Dropdown eines Balkens erstellt einen aus der Optik dieses Balkens."
L["A soft glow around the icon in this type's color. Glow size is under All."] = "Ein weiches Leuchten um das Symbol in der Farbe dieses Typs. Die Leuchtgröße steht unter Alle."
L["A spare profile in Arc UI: its groups and icons come in switched off; turn them on in their Load tab."] = "Ein Ersatzprofil in Arc UI: Seine Gruppen und Symbole kommen ausgeschaltet an; schalte sie im Tab „Laden“ ein."
L["A spark crosses the bar every 2 seconds and lands on each mana tick."] = "Alle 2 Sekunden läuft ein Funke über den Balken und landet bei jedem Manatick."
L["A spell"] = "Ein Zauber"
L["A spell ID, a link, or the name of a spell you know."] = "Eine Zauber-ID, ein Link oder der Name eines Zaubers, den du kennst."
L["A spell ID, a link, or the name of a spell you know. Any rank of it counts unless Only this rank is on."] = "Eine Zauber-ID, ein Link oder der Name eines Zaubers, den du kennst. Jeder Rang davon zählt, außer „Nur dieser Rang“ ist an."
L["A spell ID, a link, or the name of a spell you know. Enter applies it."] = "Eine Zauber-ID, ein Link oder der Name eines Zaubers, den du kennst. Enter übernimmt es."
L["A spell ID, a spell link, or the name of a spell in your spellbook: for spells the catalog does not list."] = "Eine Zauber-ID, ein Zauberlink oder der Name eines Zaubers in deinem Zauberbuch: für Zauber, die der Katalog nicht auflistet."
L["A spell ID, or the name of a spell you know. Any rank works: the bar follows the rank you know."] = "Eine Zauber-ID oder der Name eines Zaubers, den du kennst. Jeder Rang funktioniert: Der Balken folgt dem Rang, den du kennst."
L["A spell ID, or the name of a spell you know. It goes on the first empty spot; one you have not learned yet shows grey until you do."] = "Eine Zauber-ID oder der Name eines Zaubers, den du kennst. Er kommt auf den ersten freien Platz; ein noch nicht erlernter wird grau angezeigt, bis du ihn lernst."
L["A spell ID, or the name of a spell you know. The rank you know is checked."] = "Eine Zauber-ID oder der Name eines Zaubers, den du kennst. Geprüft wird der Rang, den du kennst."
L["A spell became usable"] = "Ein Zauber wurde benutzbar"
L["A spell is on cooldown"] = "Ein Zauber ist auf Abklingzeit"
L["A spell is ready"] = "Ein Zauber ist bereit"
L["A spell is recharging"] = "Ein Zauber lädt auf"
L["A spell is usable"] = "Ein Zauber ist benutzbar"
L["A spell name or ID, such as Raptor Strike, Heroic Strike, Cleave or Maul. "] = "Ein Zaubername oder eine ID, z. B. Raptorstoß, Heldenhafter Stoß, Spalten oder Zermalmen. "
L["A spell stopped being usable"] = "Ein Zauber ist nicht mehr benutzbar"
L["A spell's charges"] = "Die Aufladungen eines Zaubers"
