L["A spot mid-screen where your cooldowns pulse as they come back."] = "Ein Punkt in der Bildschirmmitte, an dem deine Abklingzeiten pulsieren, wenn sie zurückkehren."
L["A stance, form or aura from your stance bar. The icon lights up while you are in it."] = "Eine Haltung, Gestalt oder Aura deiner Haltungsleiste. Das Symbol leuchtet auf, solange du darin bist."
L["A string to share this skin."] = "Ein String, um diesen Skin zu teilen."
L["A swipe over each icon while it is on cooldown."] = "Ein Wischeffekt über jedem Symbol, solange es auf Abklingzeit ist."
L["A tick where each proc of this deck landed. A new deck clears them."] = "Eine Markierung dort, wo jeder Proc dieses Decks eintraf. Ein neues Deck löscht sie."
L["A totem is gone"] = "Ein Totem ist verschwunden"
L["A totem or guardian in its slot, or one of them by the spell that puts it down."] = "Ein Totem oder Wächter in seinem Platz, oder einer von ihnen über den Zauber, der ihn aufstellt."
