L["Anyone lacks it: a buff the whole group needs. Nobody has it: a buff kept on one member, like Beacon of Light or Earth Shield."] = "Jemand hat es nicht: ein Stärkungseffekt, den die ganze Gruppe braucht. Niemand hat es: ein Stärkungseffekt auf einem einzelnen Mitglied, wie Flamme des Glaubens oder Erdschild."
