L["Anyone: any copy fills the bar. Me: only yours or your pet's. Anyone but me: only copies from other players."] = "Jeder: Jede Kopie füllt den Balken. Ich: nur deine oder die deines Begleiters. Jeder außer mir: nur Kopien anderer Spieler."
L["Anyone: any copy lights the icon. Me: only yours or your pet's. Anyone but me: only copies from other players."] = "Jeder: Jede Kopie lässt das Symbol aufleuchten. Ich: nur deine oder die deines Begleiters. Jeder außer mir: nur Kopien anderer Spieler."
