L["Copies the layout's class and talent checks to those items so they load where the layout does. Load When rules stay."] = "Kopiert die Klassen- und Talentprüfungen des Layouts auf diese Einträge, damit sie dort geladen werden, wo das Layout lädt. „Laden, wenn“-Regeln bleiben."
