L["Copies the rows of this sub-panel onto the chosen target. Copy semantics - no live link; the target keeps its own values from then on."] = "Kopiert die Zeilen dieses Unterbereichs auf das gewählte Ziel. Es wird nur kopiert, ohne Verknüpfung; das Ziel behält ab dann seine eigenen Werte."
L["Copies the selection to the picked place and leaves the originals. Each copy keeps its settings, name and position."] = "Kopiert die Auswahl an den gewählten Ort und lässt die Originale bestehen. Jede Kopie behält ihre Einstellungen, ihren Namen und ihre Position."
L["Copies this group's class and spec checks onto those icons, so they load wherever the group does."] = "Kopiert die Klassen- und Spezialisierungsprüfungen dieser Gruppe auf diese Symbole, damit sie überall laden, wo die Gruppe lädt."
L["Copies this group's class checks onto those icons, so they load wherever the group does."] = "Kopiert die Klassenprüfungen dieser Gruppe auf diese Symbole, damit sie überall laden, wo die Gruppe lädt."
