L["Each band colors its point and every point after it."] = "Jeder Bereich färbt seinen Punkt und jeden Punkt danach."
L["Each band colors the countdown under its share of the whole time."] = "Jeder Bereich färbt den Countdown unterhalb seines Anteils an der Gesamtzeit."
L["Each band that shows in turn, nearest first, then the look with no target, one and a half seconds each."] = "Jeder Bereich, der erscheint, nacheinander, der nächste zuerst, dann die Optik ohne Ziel, je anderthalb Sekunden."
L["Each change"] = "Jede Änderung"
L["Each element's own"] = "Jeweils eigene des Elements"
L["Each element's own, %d higher"] = "Jeweils eigene des Elements, %d höher"
L["Each element's own, %d lower"] = "Jeweils eigene des Elements, %d niedriger"
L["Each icon group, and your free icons, gets a skin you pick in Masque's options: picture size and crop, border, backdrop and gloss."] = "Jede Symbolgruppe und deine freien Symbole erhalten einen Skin, den du in den Optionen von Masque wählst: Bildgröße und Zuschnitt, Rahmen, Hintergrund und Glanz."
L["Each icon shows only while its buff is missing, in combat too."] = "Jedes Symbol erscheint nur, solange sein Stärkungseffekt fehlt, auch im Kampf."
L["Each icon's Text > Custom Text & Keybind sets the text's size, color and position."] = "Text > Eigener Text & Tastenbelegung jedes Symbols legt Größe, Farbe und Position des Textes fest."
L["Each number in the custom list wears its own colour, in the order you typed them; the Tick color is the first."] = "Jede Zahl in der eigenen Liste hat ihre eigene Farbe, in der Reihenfolge deiner Eingabe; die Markierungsfarbe ist die erste."
L["Each power (druid forms)"] = "Jede Ressource (Druidengestalten)"
L["Each rule: when something happens, only if its conditions hold, then what it does."] = "Jede Regel: Wenn etwas passiert, nur wenn ihre Bedingungen erfüllt sind, dann was sie tut."
L["Each shows in its own slot while its aura is missing; the pulse keeps its spot."] = "Jedes erscheint an seinem eigenen Platz, solange seine Aura fehlt; der Puls behält seinen Platz."
L["Each spec"] = "Jede Spezialisierung"
L["Each spell's or item's name beside its icon."] = "Der Name jedes Zaubers oder Gegenstands neben seinem Symbol."
