L["Emity's latest version: a Defences row, a row for trinkets and potions, poison reminders for both hands, gradient bars, and long cooldowns shown only while on cooldown."] = "Emitys neueste Version: eine Verteidigungszeile, eine Zeile für Schmuck und Tränke, Gifterinnerungen für beide Hände, Verlaufsbalken und lange Abklingzeiten, die nur während der Abklingzeit angezeigt werden."
L["Emity's latest version: a Defences row, a row for trinkets, a potion, your weapon enchant and stance, a new DPS rotation row, gradient bars, and long cooldowns shown only while on cooldown."] = "Emitys neueste Version: eine Verteidigungszeile, eine Zeile für Schmuck, einen Trank, deine Waffenverzauberung und Haltung, eine neue DPS-Rotationszeile, Verlaufsbalken und lange Abklingzeiten, die nur während der Abklingzeit angezeigt werden."
L["Emity's latest version: a Defences row, a row for trinkets, potions and your weapon enchant, more buffs, and long cooldowns shown only while on cooldown."] = "Emitys neueste Version: eine Verteidigungszeile, eine Zeile für Schmuck, Tränke und deine Waffenverzauberung, mehr Stärkungseffekte und lange Abklingzeiten, die nur während der Abklingzeit angezeigt werden."
L["Emity's latest version: a Defences row, a row for trinkets, potions, mana gems, your weapon enchant and armor, gradient bars, and long cooldowns shown only while on cooldown."] = "Emitys neueste Version: eine Verteidigungszeile, eine Zeile für Schmuck, Tränke, Manaedelsteine, deine Waffenverzauberung und Rüstung, Verlaufsbalken und lange Abklingzeiten, die nur während der Abklingzeit angezeigt werden."
L["Emity's latest version: a Defences row, a row for trinkets, potions, your weapon enchant and aspect, a new rotation row, gradient bars, and long cooldowns shown only while on cooldown."] = "Emitys neueste Version: eine Verteidigungszeile, eine Zeile für Schmuck, Tränke, deine Waffenverzauberung und Aspekt, eine neue Rotationszeile, Verlaufsbalken und lange Abklingzeiten, die nur während der Abklingzeit angezeigt werden."
L["Emity's latest version: a Defences row, a row for trinkets, potions, your weapon enchant and aura, Turn Undead, gradient bars, and long cooldowns shown only while on cooldown."] = "Emitys neueste Version: eine Verteidigungszeile, eine Zeile für Schmuck, Tränke, deine Waffenverzauberung und Aura, Untote vertreiben, Verlaufsbalken und lange Abklingzeiten, die nur während der Abklingzeit angezeigt werden."
L["Emity's latest version: a Defences row, a row for trinkets, potions, your weapon enchant and form, more target debuffs, and long cooldowns shown only while on cooldown."] = "Emitys neueste Version: eine Verteidigungszeile, eine Zeile für Schmuck, Tränke, deine Waffenverzauberung und Gestalt, mehr Schwächungszauber auf dem Ziel und lange Abklingzeiten, die nur während der Abklingzeit angezeigt werden."
L["Emity's latest version: a Defences row, a row for trinkets, potions, your weapon enchant and form, the racial priest spells, gradient bars, and long cooldowns shown only while on cooldown."] = "Emitys neueste Version: eine Verteidigungszeile, eine Zeile für Schmuck, Tränke, deine Waffenverzauberung und Gestalt, die Volkszauber der Priester, Verlaufsbalken und lange Abklingzeiten, die nur während der Abklingzeit angezeigt werden."
L["Emity's latest version: a Defences row, a row for trinkets, potions, your weapon enchant and soul shards, more debuffs, gradient bars, and long cooldowns shown only while on cooldown."] = "Emitys neueste Version: eine Verteidigungszeile, eine Zeile für Schmuck, Tränke, deine Waffenverzauberung und Seelensplitter, mehr Schwächungszauber, Verlaufsbalken und lange Abklingzeiten, die nur während der Abklingzeit angezeigt werden."
