L["Every icon in this layout uses these looks unless it sets its own."] = "Jedes Symbol in diesem Layout nutzt diese Optiken, sofern es keine eigene festlegt."
L["Every item of this kind: the icon follows the one you last used, as the Cooldown Manager's does."] = "Jeder Gegenstand dieser Art: Das Symbol folgt dem zuletzt benutzten, wie beim Abklingzeitmanager."
