L["Every rank of the buff, and its group version, separated by commas or spaces. A member counts as having it with any of them on."] = "Jeder Rang des Stärkungseffekts und seine Gruppenversion, durch Kommas oder Leerzeichen getrennt. Ein Mitglied gilt als im Besitz, wenn eines davon aktiv ist."
L["Every row on this page back to Arc's value. It asks whether the items you have change too."] = "Jede Zeile dieser Seite zurück auf den Wert von Arc. Fragt, ob sich auch die vorhandenen Einträge ändern."
L["Every stack added runs its own timer (the rule's seconds, else Default seconds) and drops off when it ends."] = "Jeder hinzugefügte Stapel hat seinen eigenen Timer (die Sekunden der Regel, sonst Standardsekunden) und fällt weg, wenn er endet."
