L["Finds layouts, groups, icons and bars by name or ID, and options by name. Click a result to jump to it. Enter opens the top one."] = "Findet Layouts, Gruppen, Symbole und Balken nach Name oder ID sowie Optionen nach Name. Klicke auf ein Ergebnis, um dorthin zu springen. Enter öffnet das oberste."
L["Finds the spells and items on your action bars and lets you pick which become icons in this group. Out of combat only."] = "Findet die Zauber und Gegenstände auf deinen Aktionsleisten und lässt dich wählen, welche in dieser Gruppe zu Symbolen werden. Nur außerhalb des Kampfes."
