L["Fires as soon as the spell's own requirement is met (a proc, enough mana), even while it is on cooldown."] = "Löst aus, sobald die eigene Voraussetzung des Zaubers erfüllt ist (ein Proc, genug Mana), auch während er auf Abklingzeit ist."
L["Fires each time the game updates this spell's cooldown, and for some buffs as they come and go."] = "Löst jedes Mal aus, wenn das Spiel die Abklingzeit dieses Zaubers aktualisiert, und bei manchen Stärkungseffekten, wenn sie kommen und gehen."
L["Fires only while the spell's proc glow is up, on top of the trigger's own timing. An item checks its use spell."] = "Löst nur aus, solange das Proc-Leuchten des Zaubers aktiv ist, zusätzlich zum eigenen Timing des Auslösers. Ein Gegenstand prüft seinen Benutzen-Zauber."
L["Fires the first trigger once, as it will in play, even where the conditions would keep it quiet."] = "Löst den ersten Auslöser einmal aus, wie im Spiel, auch wenn die Bedingungen ihn sonst stumm halten würden."
