L["Hide while editing"] = "Beim Bearbeiten ausblenden"
L["Hides between casts; shows a sample cast while this window is open."] = "Blendet sich zwischen Zaubern aus; zeigt bei offenem Fenster einen Beispielzauber."
L["Hides casts you cannot interrupt. In combat the game hides that from addons, so it cannot drive sounds or alerts."] = "Blendet Zauber aus, die du nicht unterbrechen kannst. Im Kampf verbirgt das Spiel dies vor Addons, daher kann es keine Sounds oder Alarme auslösen."
L["Hides it on screen while this window is open, so you can get at what sits under it. Closing the window shows it again."] = "Blendet es auf dem Bildschirm aus, solange dieses Fenster offen ist, damit du an das herankommst, was darunter liegt. Beim Schließen des Fensters erscheint es wieder."
L["Hides the game's castbar under your character while this castbar is loaded. Turn off to bring it back on your next cast."] = "Blendet den Zauberbalken des Spiels unter deinem Charakter aus, solange dieser Zauberbalken geladen ist. Ausschalten, um ihn beim nächsten Zauber zurückzubringen."
L["Hides the minimap button. %s always opens this window. Drag the button along the rim to move it, right-click for move mode."] = "Blendet die Minikarten-Taste aus. %s öffnet dieses Fenster immer. Ziehe die Taste am Rand entlang, um sie zu verschieben, Rechtsklick für den Verschiebemodus."
L["Hides this update here until the next version. The tag on the layout in the sidebar stays."] = "Blendet dieses Update hier bis zur nächsten Version aus. Die Markierung am Layout in der Seitenleiste bleibt."
L["Hides while the unit is not there; always shows while this window is open."] = "Blendet sich aus, solange die Einheit nicht da ist; wird bei offenem Fenster immer gezeigt."
L["High threat"] = "Hohe Bedrohung"
L["Highest rank"] = "Höchster Rang"
L["Highlight color"] = "Hervorhebungsfarbe"
