L["Holds"] = "Hält"
L["Holds %s."] = "Hält %s."
L["Holds on every power."] = "Gilt bei jeder Ressource."
L["Holds only while the bar shows %s."] = "Hält nur, solange der Balken %s zeigt."
L["Holds the proc glow lit on a ready icon."] = "Hält das Proc-Leuchten auf einem bereiten Symbol an."
L["Holds the ready glow lit."] = "Hält das Bereit-Leuchten an."
