L["Holy Power"] = "Heilige Kraft"
L["Home"] = "Start"
L["Horizontal"] = "Horizontal"
L["Horizontal packs each row sideways; Vertical packs each column up or down."] = "Horizontal packt jede Zeile seitwärts; Vertikal packt jede Spalte nach oben oder unten."
L["Hot chance color"] = "Farbe bei heißer Chance"
L["Hot from (%)"] = "Heiß ab (%)"
L["Hover a frame on screen, a game frame or one of your Arc Auras items, and click it. Right-click or Esc cancels."] = "Fahre mit der Maus über einen Frame auf dem Bildschirm, einen Spiel-Frame oder eines deiner Elemente von Arc Auras, und klicke ihn an. Rechtsklick oder Esc bricht ab."
L["Hover a game frame on screen and click it. Right-click or Esc cancels."] = "Fahre mit der Maus über einen Spiel-Frame auf dem Bildschirm und klicke ihn an. Rechtsklick oder Esc bricht ab."
L["Hover a game frame, an action button, a Cooldown Manager icon or an Arc Auras icon and left-click it. Right-click or Esc cancels."] = "Fahre mit der Maus über einen Spiel-Frame, eine Aktionstaste, ein Symbol des Abklingzeitmanagers oder ein Arc-Auras-Symbol und klicke es mit links an. Rechtsklick oder Esc bricht ab."
L["Hovering an icon shows its spell, item or totem tooltip."] = "Beim Darüberfahren zeigt ein Symbol den Tooltip seines Zaubers, Gegenstands oder Totems."
L["How big the preview is against the bar's real size. Click to fit the whole bar in view again."] = "Wie groß die Vorschau im Vergleich zur echten Größe des Balkens ist. Klicke, um wieder den ganzen Balken einzupassen."
L["How countdown numbers round. Up: 13.2 reads 14, like action bar cooldowns. Down: 13.2 reads 13, like buff timers and nameplates."] = "Wie Countdown-Zahlen gerundet werden. Aufrunden: 13,2 wird zu 14, wie bei Abklingzeiten der Aktionsleiste. Abrunden: 13,2 wird zu 13, wie bei Stärkungseffekt-Timern und Namensplaketten."
L["How far the glow reaches past the icon: 1 sits on its edge."] = "Wie weit das Leuchten über das Symbol hinausreicht: 1 sitzt auf seinem Rand."
L["How far your target is, in colored range bands you can edit."] = "Wie weit dein Ziel entfernt ist, in farbigen Reichweitenbereichen, die du bearbeiten kannst."
L["How fast a line is spoken. 0 follows WoW's own speech rate."] = "Wie schnell eine Zeile gesprochen wird. 0 folgt der eigenen Sprechgeschwindigkeit von WoW."
L["How it looks in each state"] = "Wie es in jedem Zustand aussieht"
L["How it shows"] = "Wie es erscheint"
L["How long a flash shows. A held button keeps the highlight at least this long, so clicks that cast on release still show."] = "Wie lange ein Aufblitzen angezeigt wird. Eine gehaltene Taste behält die Hervorhebung mindestens so lange, damit auch Klicks, die erst beim Loslassen zaubern, noch angezeigt werden."
L["How long after that rule last fired this one may fire (Not after: may not fire). Enter applies it."] = "Wie lange nach dem letzten Auslösen jener Regel diese auslösen darf (Nicht nach: darf nicht auslösen). Enter übernimmt es."
L["How long it shows after each cast."] = "Wie lange es nach jedem Zauber angezeigt wird."
L["How long the bar takes to fade away when a cast ends (after the hold, when that is on). 0 = it goes at once."] = "Wie lange der Balken zum Verblassen braucht, wenn ein Zauber endet (nach dem Halten, falls aktiv). 0 = er verschwindet sofort."
L["How long the button glow takes to fade when it stops. 0: it goes at once."] = "Wie lange das Tasten-Leuchten zum Verblassen braucht, wenn es endet. 0: Es verschwindet sofort."
L["How long the timer runs when a rule starts it with no seconds of its own. Enter applies it."] = "Wie lange der Timer läuft, wenn eine Regel ihn ohne eigene Sekunden startet. Enter übernimmt es."
L["How long the timer runs, and each stack when stacks run out on their own, when a rule gives no seconds. Enter applies it."] = "Wie lange der Timer läuft, und jeder Stapel, wenn Stapel einzeln ablaufen, falls eine Regel keine Sekunden vorgibt. Enter übernimmt es."
L["How long the timer runs, or an added stack lasts; 0 takes the item's Default seconds. Decimals work (1.5). Enter applies it."] = "Wie lange der Timer läuft oder ein hinzugefügter Stapel hält; 0 nimmt die Standardsekunden des Eintrags. Dezimalzahlen funktionieren (1.5). Enter übernimmt es."
L["How long, in seconds; decimals work (1.5). Enter applies it."] = "Wie lange, in Sekunden; Dezimalzahlen funktionieren (1.5). Enter übernimmt es."
L["How many"] = "Wie viele"
L["How many charges are up; Blank at zero below hides the 0."] = "Wie viele Aufladungen verfügbar sind; „Leer bei null“ unten blendet die 0 aus."
L["How many in your party or raid have a buff."] = "Wie viele in deiner Gruppe oder deinem Schlachtzug einen Stärkungseffekt haben."
L["How many nameplates get a row, in the order the game numbers them. Each one keeps a set of frames ready."] = "Wie viele Namensplaketten eine Zeile bekommen, in der Reihenfolge, in der das Spiel sie nummeriert. Jede hält einen Satz Frames bereit."
L["How many rows of auras show, each Columns wide; up to 40 auras. The rest show as others end."] = "Wie viele Zeilen von Auren angezeigt werden, jede „Spalten“ breit; bis zu 40 Auren. Der Rest erscheint, wenn andere enden."
L["How many stacks the next spender eats; the chance is for that many draws."] = "Wie viele Stapel der nächste Verbraucher frisst; die Chance gilt für so viele Ziehungen."
L["How many you carry, on items that stack, such as potions."] = "Wie viele du dabeihast, bei stapelbaren Gegenständen wie Tränken."
L["How the bar looks in each state"] = "Wie der Balken in jedem Zustand aussieht"
L["How visible the icon is %s."] = "Wie sichtbar das Symbol ist, %s."
