L["How visible the icon is until this opacity starts. 0 hides it."] = "Wie sichtbar das Symbol ist, bis diese Transparenz beginnt. 0 blendet es aus."
L["How visible the icon is while the aura is up, until Active's opacity starts."] = "Wie sichtbar das Symbol ist, solange die Aura aktiv ist, bis die Transparenz von „Aktiv“ beginnt."
L["How visible the icon is while this look shows. 0 hides it."] = "Wie sichtbar das Symbol ist, solange diese Optik angezeigt wird. 0 blendet es aus."
