L["Its bars become a new layout of groups: same spells, sizes and places. Then it turns off."] = "Seine Balken werden zu einem neuen Layout aus Gruppen: gleiche Zauber, Größen und Plätze. Danach schaltet es sich aus."
L["Its buff"] = "Sein Stärkungseffekt"
