L["Loads only once you know %s."] = "Lädt erst, wenn du %s kennst."
L["Loads only once you know %s. Known now."] = "Lädt erst, wenn du %s kennst. Jetzt bekannt."
L["Loads only once you know %s. Not known now."] = "Lädt erst, wenn du %s kennst. Jetzt nicht bekannt."
L["Loads only while EVERY checked condition is true. Unloaded, it is fully gone, and returns when that changes, in combat too."] = "Wird nur geladen, solange JEDE angehakte Bedingung erfüllt ist. Nicht geladen, ist es komplett weg und kehrt zurück, sobald sich das ändert, auch im Kampf."
L["Loads only while EVERY checked condition is true. Unloaded, it is hidden and returns when that changes. Aura sounds still play."] = "Wird nur geladen, solange JEDE angehakte Bedingung erfüllt ist. Nicht geladen, ist es ausgeblendet und kehrt zurück, sobald sich das ändert. Aura-Sounds spielen weiter."
L["Loads only while at least one checked condition is true. Unloaded, it is fully gone, and returns when that changes, in combat too."] = "Wird nur geladen, solange mindestens eine angehakte Bedingung erfüllt ist. Nicht geladen, ist es komplett weg und kehrt zurück, sobald sich das ändert, auch im Kampf."
L["Loads only while at least one checked condition is true. Unloaded, it is hidden and returns when that changes. Aura sounds still play."] = "Wird nur geladen, solange mindestens eine angehakte Bedingung erfüllt ist. Nicht geladen, ist es ausgeblendet und kehrt zurück, sobald sich das ändert. Aura-Sounds spielen weiter."
L["Loads only while you don't know %s."] = "Lädt nur, solange du %s nicht kennst."
L["Loads only while you don't know %s. Known now."] = "Lädt nur, solange du %s nicht kennst. Jetzt bekannt."
L["Loads only while you don't know %s. Not known now."] = "Lädt nur, solange du %s nicht kennst. Jetzt nicht bekannt."
L["Loads only while you wear at least %d of %s (%d worn now)."] = "Lädt nur, solange du mindestens %d von %s trägst (jetzt %d getragen)."
