L["Not loaded on this character. It loads on: %s. Click to show it while this window is open. Conditions stay as they are."] = "Auf diesem Charakter nicht geladen. Es lädt bei: %s. Klicke, um es anzuzeigen, solange dieses Fenster offen ist. Bedingungen bleiben unverändert."
L["Not loaded on this character. It loads on: %s. The sidebar View keeps it off screen; Everything shows it."] = "Auf diesem Charakter nicht geladen. Es lädt bei: %s. Die Ansicht der Seitenleiste hält es vom Bildschirm fern; „Alles“ zeigt es."
L["Not now"] = "Jetzt nicht"
L["Not on this character's stance bar: it lights up on one that has it."] = "Nicht auf der Haltungsleiste dieses Charakters: Es leuchtet bei einem, der es hat."
L["Not right? Delete the layout and import it again."] = "Nicht richtig? Lösche das Layout und importiere es erneut."
L["Not set"] = "Nicht festgelegt"
L["Not shown"] = "Nicht angezeigt"
