L["Nothing picked yet - click a talent to pick it."] = "Noch nichts gewählt - klicke ein Talent an, um es zu wählen."
L["Nothing picked yet: click an Arc Proc above."] = "Noch nichts gewählt: Klicke oben einen Arc Proc an."
L["Nothing required yet - click a talent to require it, again to exclude it."] = "Noch nichts gefordert - klicke ein Talent, um es zu fordern, erneut, um es auszuschließen."
