L["Off. Tick the box at the top of the card to change these."] = "Aus. Hake das Kästchen oben auf der Karte an, um diese zu ändern."
L["Off: a Nature wolf's arrival counts as the proc. On: the Cooldown Manager's Doom Winds icon does, so keep it shown there."] = "Aus: Das Erscheinen eines Naturwolfs zählt als Proc. An: Das Symbol von Schicksalswinde im Abklingzeitmanager zählt, also lass es dort angezeigt."
L["Off: a recharging point is its own color at half brightness."] = "Aus: Ein Punkt, der sich auflädt, hat seine eigene Farbe bei halber Helligkeit."
L["Off: an icon not yet reached is greyed out."] = "Aus: Ein noch nicht erreichtes Symbol ist ausgegraut."
L["Off: every %s loads them, each by its own specs and talents. Cast bars always stay on %s."] = "Aus: Alle Charaktere der Klasse %s laden sie, jeweils nach eigenen Spezialisierungen und Talenten. Zauberbalken bleiben immer bei %s."
L["Off: silent while you are in a party."] = "Aus: stumm, solange du in einer Gruppe bist."
L["Off: silent while you are in a raid group."] = "Aus: stumm, solange du in einem Schlachtzug bist."
L["Off: silent while you are not in a group."] = "Aus: stumm, solange du nicht in einer Gruppe bist."
L["Off: the bar shows its no-band look while the target is in this band."] = "Aus: Der Balken zeigt seine Optik ohne Bereich, solange das Ziel in diesem Bereich ist."
L["Off: this trigger plays its sound or speech only, with no pulse."] = "Aus: Dieser Auslöser spielt nur seinen Sound oder seine Sprachausgabe ab, ohne Puls."
L["Off: this trigger pulses silently. A new trigger starts silent."] = "Aus: Dieser Auslöser pulsiert stumm. Ein neuer Auslöser startet stumm."
L["Offset X"] = "Versatz X"
L["Offset Y"] = "Versatz Y"
L["On %s."] = "Auf %s."
L["On a nameplate the bar hides while this window is open; the preview shows it."] = "Auf einer Namensplakette wird der Balken bei offenem Fenster ausgeblendet; die Vorschau zeigt ihn."
L["On anchor %d, %s."] = "Auf Anker %d, %s."
L["On cooldown"] = "Auf Abklingzeit"
L["On cooldown alpha"] = "Abklingzeit-Transparenz"
L["On cooldown opacity starts near the end"] = "Abklingzeit-Transparenz beginnt kurz vor Ende"
L["On cooldown starts with this many seconds left"] = "„Auf Abklingzeit“ ab so vielen Sekunden Rest"
L["On cooldown's opacity waits until little time is left; before that the icon takes Before that's opacity."] = "Die Transparenz von „Auf Abklingzeit“ greift erst, wenn nur noch wenig Zeit bleibt; davor nutzt das Symbol die Transparenz von „Davor“."
L["On it now: %s."] = "Gerade darauf: %s."
L["On proc"] = "Bei Proc"
L["On proc (proc glow turns on)"] = "Bei Proc (Proc-Leuchten geht an)"
L["On ranked realms, follow whichever rank of this spell you know now."] = "Auf Realms mit Rängen dem Rang dieses Zaubers folgen, den du gerade kennst."
L["On ranked realms, read whichever rank of this spell you know now."] = "Auf Realms mit Rängen den Rang dieses Zaubers lesen, den du gerade kennst."
L["On ranked realms, track whichever rank of this spell you currently know. Re-resolves on spell changes."] = "Auf Realms mit Rängen den Rang dieses Zaubers verfolgen, den du gerade kennst. Wird bei Zauberänderungen neu aufgelöst."
L["On screen"] = "Auf dem Bildschirm"
L["On the Cooldown Manager icon for %s."] = "Auf dem Symbol des Abklingzeitmanagers für %s."
L["On the Cooldown Manager icon of %s."] = "Auf dem Symbol des Abklingzeitmanagers von %s."
L["On the Cooldown Manager icon with cooldown ID %s."] = "Auf dem Symbol des Abklingzeitmanagers mit Abklingzeit-ID %s."
L["On the action button holding %s (%s)."] = "Auf der Aktionstaste mit %s (%s)."
L["On the action button holding %s."] = "Auf der Aktionstaste mit %s."
L["On the action button with %s."] = "Auf der Aktionstaste mit %s."
L["On the bar"] = "Auf dem Balken"
L["On the group"] = "An der Gruppe"
L["On the icon with cooldown ID %s."] = "Auf dem Symbol mit Abklingzeit-ID %s."
L["On this icon"] = "Auf diesem Symbol"
L["On top"] = "Oben drauf"
L["On unit"] = "Auf Einheit"
L["On use (when cast)"] = "Beim Benutzen (beim Wirken)"
L["On your screen"] = "Auf deinem Bildschirm"
L["On: adding stacks also starts the timer over, with the seconds below."] = "An: Beim Hinzufügen von Stapeln startet auch der Timer neu, mit den Sekunden unten."
L["On: every Arc Proc resets the moment a key starts, so a reset is never missed. Off: on the gate drop, which keeps the skip working."] = "An: Jeder Arc Proc wird zurückgesetzt, sobald ein Schlüsselstein startet, sodass kein Zurücksetzen verpasst wird. Aus: beim Tor-Abfall, was das Überspringen am Laufen hält."
L["On: icons pack (Show while missing ones too). Off: every aura keeps its spot."] = "An: Symbole rücken zusammen (auch bei „Anzeigen, solange fehlend“). Aus: Jede Aura behält ihren Platz."
L["On: it glows while this look shows. Click to switch it."] = "An: Es leuchtet, solange diese Optik angezeigt wird. Klicke, um umzuschalten."
L["On: the debuffs start on the line after the buffs. Off: they follow straight on."] = "An: Die Schwächungszauber beginnen in der Zeile nach den Stärkungseffekten. Aus: Sie folgen direkt aufeinander."
L["On: the rule fires only while the conditions below hold. Off drops them."] = "An: Die Regel löst nur aus, solange die Bedingungen unten gelten. Aus entfernt sie."
L["On: the skin sets it for every bar that wears it. Off: each bar keeps its own."] = "An: Der Skin legt es für jeden Balken fest, der ihn trägt. Aus: Jeder Balken behält seinen eigenen."
L["On: the spell's own requirement decides (a proc, enough mana), even on cooldown. Off: only when it can be cast now."] = "An: Die eigene Voraussetzung des Zaubers entscheidet (ein Proc, genug Mana), auch bei Abklingzeit. Aus: nur, wenn er jetzt gewirkt werden kann."
L["On: the trigger fires for your pet's casts of the spell as well as yours."] = "An: Der Auslöser löst auch bei den Zaubern deines Begleiters aus, nicht nur bei deinen."
L["On: this opacity while none is left. Off: it keeps its opacity."] = "An: diese Transparenz, solange keines übrig ist. Aus: Es behält seine Transparenz."
L["On: this opacity while toggled on. Off: it keeps its opacity."] = "An: Diese Transparenz, solange eingeschaltet. Aus: Es behält seine Transparenz."
L["On: this trigger has its own pulse duration and animation tuning. Off drops them, and the reminder's apply."] = "An: Dieser Auslöser hat eine eigene Pulsdauer und Animationsabstimmung. Aus verwirft sie, und die der Erinnerung gelten."
L["Once an ability is off cooldown."] = "Sobald eine Fähigkeit nicht mehr auf Abklingzeit ist."
L["Once the proc glow goes, the pulse this trigger started leaves the screen, the queue and the hold."] = "Sobald das Proc-Leuchten endet, verschwindet der von diesem Auslöser gestartete Puls vom Bildschirm, aus der Warteschlange und aus dem Halten."
L["Once the spell stops being usable, the pulse this trigger started leaves the screen, the queue and the hold."] = "Sobald der Zauber nicht mehr benutzbar ist, verschwindet der von diesem Auslöser gestartete Puls vom Bildschirm, aus der Warteschlange und aus dem Halten."
L["One card per element with its preview, kind, load conditions, Edit and Delete."] = "Eine Karte pro Element mit Vorschau, Art, Ladebedingungen, Bearbeiten und Löschen."
L["One color"] = "Eine Farbe"
L["One editor for every selected icon (or bar): the rows they all share, read from the first one; a change lands on all of them."] = "Ein Editor für jedes ausgewählte Symbol (oder jeden Balken): die Zeilen, die alle gemeinsam haben, vom ersten gelesen; eine Änderung gilt für alle."
L["One layer for every element of this layout, or each element's own layer moved up or down."] = "Eine Ebene für jedes Element dieses Layouts oder die eigene Ebene jedes Elements nach oben oder unten verschoben."
L["One look"] = "Eine Optik"
L["One motion (seconds)"] = "Eine Bewegung (Sekunden)"
L["One option of a choice talent"] = "Eine Option eines Wahltalents"
L["One per tick"] = "Eines pro Tick"
L["One pulse (seconds)"] = "Ein Puls (Sekunden)"
L["One run (seconds)"] = "Ein Durchlauf (Sekunden)"
L["One stance"] = "Eine Haltung"
L["One totem, by its spell ID"] = "Ein Totem, nach seiner Zauber-ID"
L["One totem: that totem, any rank, in whatever slot it lands. A totem slot: "] = "Ein Totem: dieses Totem, jeder Rang, in welchem Platz es auch landet. Ein Totem-Platz: "
L["One you have not learned yet stays grey until you do."] = "Eines, das du noch nicht gelernt hast, bleibt grau, bis du es lernst."
L["One-time catch-up: moves EVERY action bar spell to the top rank you know, including lower ranks you placed on purpose."] = "Einmaliges Nachholen: Verschiebt JEDEN Zauber der Aktionsleisten auf den höchsten Rang, den du kennst, auch niedrigere Ränge, die du absichtlich platziert hast."
L["Only a spell row has a cost to mark."] = "Nur eine Zauberzeile hat Kosten zum Markieren."
L["Only fire when proc is active"] = "Nur auslösen, wenn der Proc aktiv ist"
L["Only if"] = "Nur wenn"
