L["Only on-use trinkets (hide passive ones)"] = "Nur Schmuck zum Benutzen (passive aus)"
L["Only out of combat"] = "Nur außerhalb des Kampfes"
L["Only the types ticked under Tracking, Dispel types, show, so only they have an icon."] = "Nur die unter Verfolgung > Bannarten angehakten Typen werden angezeigt, daher haben nur sie ein Symbol."
