L["Opens Import / Export with exactly this selection ticked and its share string ready to copy."] = "Öffnet Importieren / Exportieren mit genau dieser Auswahl angehakt und ihrem Teilen-String zum Kopieren bereit."
L["Opens Import / Export with just this reminder ticked and its share string ready to copy."] = "Öffnet Importieren / Exportieren mit nur dieser Erinnerung angehakt und ihrem String zum Teilen bereit zum Kopieren."
L["Opens Import / Export with just this ticked and its share string ready to copy."] = "Öffnet Importieren / Exportieren, nur mit diesem Eintrag angehakt und seinem Teilen-String zum Kopieren bereit."
L["Opens a picker for this group's spells and items right after Create. Out of combat only."] = "Öffnet direkt nach dem Erstellen eine Auswahl für die Zauber und Gegenstände dieser Gruppe. Nur außerhalb des Kampfes."
L["Opens every More options fold in the editors, so the fine-tuning rows show without a click. Off: they wait behind their fold."] = "Öffnet jede Falte „Weitere Optionen“ in den Editoren, sodass die Feinabstimmungszeilen ohne Klick erscheinen. Aus: Sie warten hinter ihrer Falte."
L["Opens it. The Anchor panel on its Position tab holds the link back to this one."] = "Öffnet es. Das Anker-Panel im Tab „Position“ enthält den Link zurück zu diesem."
L["Opens its editor."] = "Öffnet seinen Editor."
L["Opens the Add window aimed at this element."] = "Öffnet das Hinzufügen-Fenster, auf dieses Element ausgerichtet."
L["Opens the Add window for a spell, an item, a weapon enchant or a missing aura to be reminded of."] = "Öffnet das Hinzufügen-Fenster für einen Zauber, einen Gegenstand, eine Waffenverzauberung oder eine fehlende Aura, an die erinnert werden soll."
L["Opens the talent tree: click a talent for this rule, again for Not taken."] = "Öffnet den Talentbaum: Klicke ein Talent für diese Regel an, nochmal für „Nicht gewählt“."
L["Opens the talent tree: the bar keeps one look while you have the talent you pick, one while you don't."] = "Öffnet den Talentbaum: Der Balken behält eine Optik, solange du das gewählte Talent hast, und eine, solange du es nicht hast."
