L["Ready, a fake cooldown, then ready again (a charge spell: Ready, Recharging, No charges and back). Swipe, texts, dims and glows loop."] = "Bereit, eine Schein-Abklingzeit, dann wieder bereit (ein Aufladungszauber: Bereit, Lädt auf, Keine Aufladungen und zurück). Wischeffekt, Texte, Abdunklungen und Leuchten laufen in Schleife."
L["Ready, the timer runs, the aura is up, then the cooldown runs out to Ready again."] = "Bereit, der Timer läuft, die Aura ist aktiv, dann läuft die Abklingzeit ab und es ist wieder Bereit."
L["Ready, then a short cooldown, then ready again: the fill, threshold colours and countdown text."] = "Bereit, dann eine kurze Abklingzeit, dann wieder bereit: die Füllung, Schwellenfarben und der Countdown-Text."
