L["Text outline"] = "Textkontur"
L["Text shadow"] = "Textschatten"
L["Text size"] = "Textgröße"
L["Text threshold %d color"] = "Textschwelle %d Farbe"
L["Text threshold %d value"] = "Textschwelle %d Wert"
L["Text threshold colors"] = "Textschwellen-Farben"
L["Text thresholds in power units"] = "Textschwellen in Ressourceneinheiten"
L["Text to Speech"] = "Text-to-Speech"
L["Text to speech: when set, it is spoken instead of the sound."] = "Text-to-Speech: Wenn gesetzt, wird er statt des Sounds gesprochen."
L["Text type"] = "Texttyp"
L["Texts"] = "Texte"
L["Texts take the bar's color"] = "Texte übernehmen die Farbe des Balkens"
L["Texture"] = "Textur"
L["Texture  -  %s"] = "Textur  -  %s"
L["Texture name"] = "Texturname"
L["Textures"] = "Texturen"
L["Textures you use show here."] = "Von dir genutzte Texturen erscheinen hier."
L["That anchor target no longer exists, so it stays free."] = "Dieses Ankerziel existiert nicht mehr, daher bleibt es frei."
L["That frame can't move this way: an Arc Auras frame, the whole screen, or what this group is anchored to."] = "Dieser Frame kann so nicht bewegt werden: ein Arc-Auras-Frame, der ganze Bildschirm oder das, woran diese Gruppe verankert ist."
L["That paste came in cut short. Paste it once more."] = "Das Eingefügte kam abgeschnitten an. Füge es noch einmal ein."
L["The "] = "Der "
L["The Active look, its timer running with its swipe and duration text. Drag any text on the icon to place it."] = "Die Optik „Aktiv“, ihr Timer läuft mit Wischeffekt und Dauertext. Ziehe einen beliebigen Text auf dem Symbol, um ihn zu platzieren."
L["The Algeth'ar Puzzle Box's haste: 20 seconds from its use; dying clears it."] = "Das Tempo der Rätselbox von Algeth'ar: 20 Sekunden ab Benutzung; Sterben löscht es."
L["The Arc Proc's own"] = "Der eigene des Arc Procs"
L["The Cooldown Manager look draws the border and the shadow."] = "Die Optik des Abklingzeitmanagers zeichnet Rahmen und Schatten."
L["The Cooldown Manager look sets the picture's size, crop and shape."] = "Die Optik des Abklingzeitmanagers legt Größe, Zuschnitt und Form des Bildes fest."
L["The Cooldown Manager's cooldown IDs for spells, auras and trinkets, one line per category. Runs of IDs show as ranges."] = "Die Abklingzeit-IDs des Abklingzeitmanagers für Zauber, Auren und Schmuck, eine Zeile pro Kategorie. Folgen von IDs erscheinen als Bereiche."
L["The Cooldown Manager's soft shadow frame around the icon art."] = "Der weiche Schattenrahmen des Abklingzeitmanagers um die Symbolgrafik."
L["The ID block shows only when Shift is held as the tooltip opens."] = "Der ID-Block erscheint nur, wenn beim Öffnen des Tooltips Shift gehalten wird."
L["The ID of what the tooltip shows: a spell, aura, item, toy, mount, currency, achievement or quest."] = "Die ID dessen, was der Tooltip zeigt: Zauber, Aura, Gegenstand, Spielzeug, Reittier, Währung, Erfolg oder Quest."
L["The Light's Potential potion: 30 seconds from the drink, each drink restarts it; dying clears it."] = "Der Trank Potenzial des Lichts: 30 Sekunden ab dem Trinken, jedes Trinken startet neu; Sterben löscht es."
L["The Not active look, with no timer running."] = "Die Optik „Nicht aktiv“, ohne laufenden Timer."
L["The On cooldown look: the timer idle and its cooldown spell cooling down."] = "Die Optik „Auf Abklingzeit“: Timer untätig und sein Abklingzeit-Zauber auf Abklingzeit."
L["The Ready look: the timer idle and its cooldown spell ready."] = "Die Optik „Bereit“: Timer untätig und sein Abklingzeit-Zauber bereit."
L["The Timer running look, its timer frozen with its swipe and duration text. Drag any text on the icon to place it."] = "Die Optik „Timer läuft“, ihr Timer eingefroren mit Wischeffekt und Dauertext. Ziehe einen beliebigen Text auf dem Symbol, um ihn zu platzieren."
L["The Tracked Bars entry this bar copies. Keep the Cooldown Manager's own bar on, and hide it with opacity 0 in Edit Mode."] = "Der Eintrag der Verfolgten Leisten, den dieser Balken kopiert. Lass den eigenen Balken des Abklingzeitmanagers an und blende ihn im Bearbeitungsmodus mit Transparenz 0 aus."
L["The action bar's yellow check on the icon while it waits for your next swing."] = "Das gelbe Häkchen der Aktionsleiste auf dem Symbol, solange es auf deinen nächsten Swing wartet."
L["The art's spell"] = "Der Zauber der Grafik"
L["The aura at 3 stacks."] = "Die Aura bei 3 Stapeln."
L["The aura comes up with a fake duration (swipe and duration text), drops to its missing look, and comes back."] = "Die Aura erscheint mit einer Scheindauer (Wischeffekt und Dauertext), fällt auf ihre Optik „Fehlt“ und kehrt zurück."
L["The aura counts down, drops off, and comes back: threshold colours and the duration text."] = "Die Aura zählt herunter, fällt ab und kehrt zurück: Schwellenfarben und der Dauertext."
L["The aura icons in this group are kept for when you switch back."] = "Die Aura-Symbole in dieser Gruppe bleiben erhalten, falls du zurückwechselst."
L["The aura lasts"] = "Die Aura dauert"
L["The aura lasts (seconds)"] = "Die Aura dauert (Sekunden)"
L["The aura with 60% of its duration left."] = "Die Aura mit 60% Restdauer."
L["The aura's full length, which the game keeps from addons: seconds need it, percent does not. 0 = not set: always shown."] = "Die volle Länge der Aura, die das Spiel vor Addons verbirgt: Sekunden brauchen sie, Prozent nicht. 0 = nicht festgelegt: immer angezeigt."
L["The aura's full length. The game hides it from addons, so seconds thresholds need it. 0 = not set: the glow shows the whole time."] = "Die volle Dauer der Aura. Das Spiel verbirgt sie vor Addons, daher brauchen Sekunden-Schwellen diesen Wert. 0 = nicht gesetzt: Das Leuchten zeigt sich die ganze Zeit."
L["The aura's icon"] = "Das Symbol der Aura"
L["The aura's spell ID, or the spell whose cooldown it follows: an ID, a link or the name of a spell you know. Enter applies it."] = "Die Zauber-ID der Aura oder der Zauber, dessen Abklingzeit sie folgt: eine ID, ein Link oder der Name eines Zaubers, den du kennst. Enter übernimmt es."
L["The aura's spell IDs, comma separated."] = "Die Zauber-IDs der Aura, durch Kommas getrennt."
L["The aura's spell IDs, comma separated. Any caster's copy counts."] = "Die Zauber-IDs der Aura, durch Kommas getrennt. Die Kopie jedes Wirkenden zählt."
L["The aura's spell IDs, separated by commas or spaces. Add every rank's ID if they differ. The game shows whichever is up."] = "Die Zauber-IDs der Aura, getrennt durch Kommas oder Leerzeichen. Füge die ID jedes Rangs hinzu, falls sie sich unterscheiden. Das Spiel zeigt jeweils die aktive."
L["The aura's spell IDs, separated by commas or spaces. Tracking sets its unit."] = "Die Zauber-IDs der Aura, durch Kommas oder Leerzeichen getrennt. Die Verfolgung legt ihre Einheit fest."
L["The aura's spell IDs, separated by commas or spaces; any of them counts."] = "Die Zauber-IDs der Aura, durch Kommas oder Leerzeichen getrennt; jede davon zählt."
L["The aura's spell IDs, separated by commas or spaces; any of them shows the picture."] = "Die Zauber-IDs der Aura, durch Kommas oder Leerzeichen getrennt; jede davon zeigt das Bild."
L["The aura's spell IDs, separated by commas. A debuff usually has the ID of the spell that puts it up."] = "Die Zauber-IDs der Aura, durch Kommas getrennt. Ein Schwächungszauber hat meist die ID des Zaubers, der ihn aufbaut."
L["The band your target is in; blank with no target or a friendly one."] = "Der Bereich, in dem dein Ziel ist; leer ohne Ziel oder bei einem freundlichen."
L["The bar"] = "Der Balken"
L["The bar at 3 stacks, or at its Max stacks when that is lower."] = "Der Balken bei 3 Stapeln oder bei seinen Maximalstapeln, wenn diese niedriger sind."
L["The bar at 60%, standing still."] = "Der Balken bei 60%, im Stillstand."
L["The bar between swings."] = "Der Balken zwischen den Swings."
L["The bar in the middle of a cast, standing still."] = "Der Balken mitten in einem Zauber, im Stillstand."
L["The bar is full at this many stacks. Empty: the maximum the game reports, shown in the field. Type a number only if it is wrong."] = "Der Balken ist bei dieser Stapelzahl voll. Leer: das vom Spiel gemeldete Maximum, im Feld angezeigt. Gib nur dann eine Zahl ein, wenn es falsch ist."
L["The bar part way through its timer."] = "Der Balken auf halbem Weg durch seinen Timer."
L["The bar shows half the power; past the middle it fills again in the second half color."] = "Der Balken zeigt die halbe Ressource; hinter der Mitte füllt er sich erneut in der Farbe der zweiten Hälfte."
L["The bar with no timer running."] = "Der Balken ohne laufenden Timer."
L["The bar's look."] = "Die Optik des Balkens."
L["The bar's own look"] = "Die eigene Optik des Balkens"
L["The bars that wear it keep its look as their own."] = "Die Balken, die ihn tragen, behalten seine Optik als ihre eigene."
L["The buff this totem gives you, as its tooltip names it. The Out of range look shows while the totem is out and you lack it."] = "Der Stärkungseffekt, den dir dieses Totem gibt, so wie sein Tooltip ihn nennt. Die Optik „Außer Reichweite“ erscheint, solange das Totem draußen ist und dir der Effekt fehlt."
L["The chance climbs 1% per Riptide since the last proc."] = "Die Chance steigt um 1% je Springflut seit dem letzten Proc."
L["The chance climbs per qualifying harvest; needs the 2-piece set."] = "Die Chance steigt je zählender Ernte; braucht das 2-Teile-Set."
L["The chance of a proc"] = "Die Chance auf einen Proc"
L["The class this skin switches on for."] = "Die Klasse, für die dieser Skin eingeschaltet wird."
L["The color %s."] = "Die Farbe, %s."
L["The cooldown lasts (seconds)"] = "Die Abklingzeit dauert (Sekunden)"
L["The cooldown swipe keeps its own opacity while the icon dims, so only the art fades."] = "Der Abklingzeit-Wischeffekt behält seine eigene Transparenz, während das Symbol gedimmt wird; nur die Grafik verblasst."
L["The count"] = "Die Anzahl"
L["The count of your equipped ammo; blank with the slot empty."] = "Die Anzahl deiner angelegten Munition; leer bei leerem Platz."
L["The count the \"Ammo is low\" load and visibility condition uses. An icon's warning glow and ammo count colors have their own thresholds."] = "Die Anzahl, die die Lade- und Sichtbarkeitsbedingung „Munition niedrig“ verwendet. Das Warn-Leuchten und die Farben der Munitionsanzahl eines Symbols haben eigene Schwellen."
L["The countdown stays hidden until this many seconds are left."] = "Der Countdown bleibt verborgen, bis so viele Sekunden übrig sind."
L["The deck half drawn, with a mark where each proc landed."] = "Das Deck zur Hälfte gezogen, mit einer Markierung dort, wo jeder Proc eintraf."
L["The dim copy stays when the picture hides: no aura, no timer, a cooldown not ready."] = "Die gedimmte Kopie bleibt, wenn sich das Bild ausblendet: keine Aura, kein Timer, eine Abklingzeit nicht bereit."
L["The end of your cast that your connection's delay covers: start the next cast once the fill reaches it."] = "Das Ende deines Zaubers, das die Verzögerung deiner Verbindung abdeckt: Starte den nächsten Zauber, sobald die Füllung es erreicht."
L["The fill behind this group while the options window is open; opacity 0 means none."] = "Die Füllung hinter dieser Gruppe bei offenem Optionsfenster; Transparenz 0 bedeutet keine."
L["The fill shows how many of this deck's procs are used: none, some or all. Off: the Fill color."] = "Die Füllung zeigt, wie viele Procs dieses Decks verbraucht sind: keine, einige oder alle. Aus: die Füllfarbe."
L["The first time you log in after Arc Auras updates, a window opens once with what changed in the new version."] = "Beim ersten Einloggen nach einem Update von Arc Auras öffnet sich einmal ein Fenster mit den Änderungen der neuen Version."
L["The full look starts out of combat, or after a /reload."] = "Die volle Optik startet außerhalb des Kampfes oder nach einem /reload."
L["The game does not let addons match this aura type on that unit by spell ID."] = "Das Spiel lässt Addons diesen Auratyp auf dieser Einheit nicht per Zauber-ID abgleichen."
L["The game draws it with the aura, in combat too. Buffs work on you, your pet and friendly units; debuffs on a hostile target or focus."] = "Das Spiel zeichnet es mit der Aura, auch im Kampf. Stärkungseffekte wirken auf dich, deinen Begleiter und freundliche Einheiten; Schwächungszauber auf ein feindliches Ziel oder den Fokus."
L["The game frame's name, as Pick Frame shows it. Enter applies it."] = "Der Name des Spiel-Frames, wie „Frame wählen“ ihn zeigt. Enter übernimmt es."
L["The game holds this frame still in combat. It moves when combat ends."] = "Das Spiel hält diesen Frame im Kampf fest. Er bewegt sich, wenn der Kampf endet."
L["The game keeps an aura's length from addons, so seconds need it. A share needs none."] = "Das Spiel hält die Länge einer Aura vor Addons zurück, daher brauchen Sekunden sie. Ein Anteil braucht keine."
L["The game keeps the aura's length from addons: 0 shows the words the whole time it is up."] = "Das Spiel hält die Länge der Aura vor Addons zurück: 0 zeigt die Worte die ganze Zeit, in der sie aktiv ist."
L["The game plays aura sounds itself, so they work in combat, for anyone's copy of the aura."] = "Das Spiel spielt Aura-Sounds selbst ab, daher funktionieren sie im Kampf, für die Kopie der Aura von jedem."
L["The game plays it, in combat too; Load When and the gap between cues don't apply."] = "Das Spiel spielt es ab, auch im Kampf; „Laden, wenn“ und der Abstand zwischen Signalen gelten nicht."
L["The game protects %s, so it stays free."] = "Das Spiel schützt %s, daher bleibt es frei."
L["The game sent a spell update"] = "Das Spiel hat ein Zauber-Update gesendet"
L["The game's clock, as the minimap shows it."] = "Die Uhr des Spiels, wie die Minimap sie zeigt."
L["The game's debuff border"] = "Der Schwächungs-Rahmen des Spiels"
L["The game's own cooldown and buff icons and bars, as in its options. Items pinned to its icons stand free until it is back on."] = "Die eigenen Abklingzeit- und Stärkungssymbole und -balken des Spiels, wie in dessen Optionen. An seine Symbole angeheftete Einträge bleiben frei, bis es wieder an ist."
L["The game's own gold art, untinted, so the color steps aside. Intensity still applies."] = "Die goldene Grafik des Spiels, ungetönt, daher tritt die Farbe zurück. Die Intensität gilt weiterhin."
L["The global name of a frame, e.g. ElvUF_Player. A frame that does not exist counts as not there."] = "Der globale Name eines Frames, z. B. ElvUF_Player. Ein Frame, der nicht existiert, gilt als nicht vorhanden."
L["The global name of a game frame, e.g. PlayerFrame or ElvUF_Player."] = "Der globale Name eines Spiel-Frames, z. B. PlayerFrame oder ElvUF_Player."
L["The glow waits for combat; out of combat the bar shows without it."] = "Das Leuchten wartet auf den Kampf; außerhalb des Kampfes wird der Balken ohne es angezeigt."
L["The glow waits for combat; out of combat the icon shows without it."] = "Das Leuchten wartet auf den Kampf; außerhalb des Kampfes wird das Symbol ohne es angezeigt."
L["The green outline and dark fill around each group while this window is open. Nothing shows groups as in play. Name tabs still work."] = "Die grüne Kontur und die dunkle Füllung um jede Gruppe, solange dieses Fenster offen ist. Mit „Nichts“ erscheinen Gruppen wie im Spiel. Namens-Tabs funktionieren weiter."
L["The group"] = "Die Gruppe"
L["The group takes its %s with it."] = "Die Gruppe nimmt %s mit."
L["The group's box hugs the icons that are showing; anything anchored to it moves with it."] = "Der Kasten der Gruppe schmiegt sich an die sichtbaren Symbole; alles, was daran verankert ist, wandert mit."
L["The group's point"] = "Der Punkt der Gruppe"
L["The group's spot can't be read right now. The frame moves once it can."] = "Der Platz der Gruppe kann gerade nicht gelesen werden. Der Frame bewegt sich, sobald es möglich ist."
L["The groups take their %s with them."] = "Die Gruppen nehmen %s mit."
L["The health preview: 65% health with incoming heals and shields, in your colours and texts."] = "Die Gesundheitsvorschau: Gesundheit bei 65%, mit eingehender Heilung und Schilden, in deinen Farben und Texten."
L["The icon"] = "Das Symbol"
L["The icon and bar previews sit on this color."] = "Die Symbol- und Balkenvorschauen liegen auf dieser Farbe."
L["The icon as the game's Cooldown Manager draws it: its rounded corners, its border and shadow, and its swipe."] = "Das Symbol so, wie es der Abklingzeitmanager des Spiels zeichnet: abgerundete Ecken, Rahmen und Schatten sowie Wischeffekt."
L["The icon's cooldown ID, its exact entry in the Cooldown Manager: the crosshair on an icon fills it. Empty uses the spell above."] = "Die Abklingzeit-ID des Symbols, sein genauer Eintrag im Abklingzeitmanager: Das Fadenkreuz auf einem Symbol füllt sie aus. Leer verwendet den Zauber oben."
L["The icon's exact entry in the Cooldown Manager; Pick Frame on an icon fills it. Empty uses the spell above."] = "Der genaue Eintrag des Symbols im Abklingzeitmanager; „Frame wählen“ auf einem Symbol füllt ihn aus. Leer verwendet den Zauber oben."
L["The icon's file ID, the base icon when an override swapped the art, and the icon the button shows when that differs."] = "Die Datei-ID des Symbols, das Basissymbol, wenn eine Überschreibung die Grafik getauscht hat, und das Symbol, das die Taste zeigt, wenn es abweicht."
L["The import did not run."] = "Der Import wurde nicht ausgeführt."
L["The internal cooldown as a timer: 45 s, less with Natural Harmony."] = "Die interne Abklingzeit als Timer: 45 s, weniger mit Naturgegebene Harmonie."
L["The item"] = "Der Eintrag"
L["The item's own stacks, before this rule acts. Empty = no such condition."] = "Die eigenen Stapel des Eintrags, bevor diese Regel wirkt. Leer = keine solche Bedingung."
L["The item, or several: the icon shows the first one you carry and can use."] = "Der Gegenstand oder mehrere: Das Symbol zeigt den ersten, den du dabei hast und benutzen kannst."
L["The items that used the old values take the new ones."] = "Die Einträge, die die alten Werte nutzten, übernehmen die neuen."
L["The items you have keep their look; only new ones start with these. Leaving the page does the same."] = "Die vorhandenen Einträge behalten ihre Optik; nur neue starten mit diesen. Das Verlassen der Seite bewirkt dasselbe."
L["The kinds that take this page's rows, each where it has the row. Nothing happens until you press Copy."] = "Die Arten, die die Zeilen dieser Seite übernehmen, jede dort, wo sie die Zeile hat. Es passiert nichts, bis du Kopieren drückst."
L["The label's own color"] = "Die eigene Farbe der Beschriftung"
L["The layout's center point"] = "Der Mittelpunkt des Layouts"
L["The layout's distance from the spot it's pinned to, in whole units."] = "Der Abstand des Layouts von der Stelle, an der es angeheftet ist, in ganzen Einheiten."
L["The line to speak."] = "Die zu sprechende Zeile."
L["The look the rows below change. The bar shows it while you edit; anything a look leaves alone follows the bar's own."] = "Die Optik, die die Zeilen unten ändern. Der Balken zeigt sie beim Bearbeiten; alles, was eine Optik unberührt lässt, folgt der eigenen des Balkens."
L["The look the rows below edit. Bar's own applies when no skin does. A skin applies when its conditions hold, first from the top."] = "Die Optik, die die Zeilen unten bearbeiten. „Eigene des Balkens“ gilt, wenn kein Skin greift. Ein Skin gilt, wenn seine Bedingungen zutreffen, von oben der erste."
L["The look while the aura is missing: the ghost with its Missing icon, alpha and desaturation."] = "Die Optik, solange die Aura fehlt: der Geist mit seinem Fehlt-Symbol, Transparenz und Ausgrauen."
L["The look while the aura is up: Aura Active art, alpha, tint, border and glow. Drag any text to place it."] = "Die Optik, solange die Aura aktiv ist: Grafik, Transparenz, Tönung, Rahmen und Leuchten von Aura aktiv. Ziehe einen beliebigen Text, um ihn zu platzieren."
L["The look while the aura is up: its button over the cooldown, in the Aura Active look, with stacks. Drag texts to place them."] = "Die Optik, solange die Aura aktiv ist: ihre Taste über der Abklingzeit, in der Optik von Aura aktiv, mit Stapeln. Ziehe Texte, um sie zu platzieren."
L["The look while you are in the stance (any stance, for your current one). Drag any text on the icon to place it."] = "Die Optik, solange du in der Haltung bist (eine beliebige Haltung, bei deiner aktuellen). Ziehe einen beliebigen Text auf dem Symbol, um ihn zu platzieren."
L["The look while you are not in it (no stance, for your current one)."] = "Die Optik, solange du nicht darin bist (keine Haltung, bei deiner aktuellen)."
L["The mana the next tick adds glows past the fill, brightens as the tick nears, then lands. Empty while the five-second rule runs."] = "Das Mana, das der nächste Tick hinzufügt, leuchtet über die Füllung hinaus, wird heller, je näher der Tick rückt, und landet dann. Leer, solange die Fünf-Sekunden-Regel läuft."
L["The middle of your screen"] = "Die Mitte deines Bildschirms"
L["The mirror is not loaded."] = "The mirror is not loaded."
L["The move did not run."] = "Das Verschieben wurde nicht ausgeführt."
L["The nearest band that shows, standing still."] = "Der nächste Bereich, der erscheint, im Stillstand."
L["The new look shows after a reload"] = "Die neue Optik erscheint nach einem Neuladen"
L["The next tick"] = "Der nächste Tick"
L["The number beside a marker that comes back in a later swing."] = "Die Zahl neben einer Markierung, die in einem späteren Swing zurückkehrt."
L["The numeric item ID."] = "Die numerische Gegenstands-ID."
L["The opacity starts with this many seconds left."] = "Die Transparenz beginnt, wenn noch so viele Sekunden übrig sind."
L["The original bright cyan."] = "Das ursprüngliche leuchtende Cyan."
L["The pack items you deleted come back with this update. Unticked, they stay deleted."] = "Die von dir gelöschten Paketeinträge kommen mit diesem Update zurück. Ohne Haken bleiben sie gelöscht."
L["The pack's name. Whoever imports the string sees it first."] = "Der Name des Pakets. Wer den String importiert, sieht ihn zuerst."
L["The part of a shield that doesn't fit past full health draws over the end of the health, so a shield on a full-health unit still shows."] = "Der Teil eines Schilds, der nicht über die volle Gesundheit hinaus passt, wird über das Ende der Gesundheit gezeichnet, sodass ein Schild auf einer Einheit mit voller Gesundheit weiterhin sichtbar ist."
L["The picture again, dimmed, behind it: the empty part of a fill. It hides with the picture."] = "Das Bild erneut, gedimmt, dahinter: der leere Teil einer Füllung. Es verschwindet mit dem Bild."
L["The picture as it looks while active; a fill or a ring stands at 60%."] = "Das Bild, wie es aussieht, solange es aktiv ist; eine Füllung oder ein Ring steht bei 60%."
L["The picture grows and shrinks gently, in combat too."] = "Das Bild wächst und schrumpft sanft, auch im Kampf."
L["The picture is a sheet of frames, played in order over and over."] = "Das Bild ist ein Blatt aus Einzelbildern, die der Reihe nach immer wieder abgespielt werden."
L["The picture keeps its shape at any width and height: its edges are cropped, never stretched."] = "Das Bild behält bei jeder Breite und Höhe seine Form: Die Ränder werden zugeschnitten, nie gestreckt."
L["The picture, border, swipe, shadow and glows follow the shape."] = "Bild, Rahmen, Wischeffekt, Schatten und Leuchten folgen der Form."
L["The point of the frame that goes on the group."] = "Der Punkt des Frames, der an die Gruppe kommt."
L["The power this row holds on. All powers: whatever power the bar shows."] = "Die Ressource, bei der diese Zeile gilt. Alle Ressourcen: welche Ressource der Balken auch zeigt."
L["The pulse stays at full, with no fade, until you cast the spell or use the item, or its trigger's Clear when ends it."] = "Der Puls bleibt ohne Verblassen auf voller Stärke, bis du den Zauber wirkst oder den Gegenstand benutzt, oder bis das „Löschen, wenn“ seines Auslösers ihn beendet."
L["The ready look with no animation. Drag any text on the icon to place it."] = "Die Optik „Bereit“ ohne Animation. Ziehe einen beliebigen Text auf dem Symbol, um ihn zu platzieren."
L["The ready look, with the Ready text when it is on."] = "Die Optik „Bereit“, mit dem Bereit-Text, wenn er an ist."
L["The resize lands when you let go of the slider."] = "Die Größenänderung wird wirksam, wenn du den Regler loslässt."
L["The resource texts change color at their own power values, apart from the bar's colors."] = "Die Ressourcentexte ändern ihre Farbe bei eigenen Ressourcenwerten, unabhängig von den Farben des Balkens."
L["The resource texts wear the fill's color, the bar's own or a row's. A row's own text color wins."] = "Die Ressourcentexte tragen die Farbe der Füllung, die des Balkens oder die einer Zeile. Die eigene Textfarbe einer Zeile gewinnt."
L["The row holds for any spell left in it."] = "Die Zeile gilt für jeden darin verbliebenen Zauber."
L["The rule fires only while this spell is off its cooldown (the GCD never counts). Empty = no such condition."] = "Die Regel löst nur aus, solange dieser Zauber nicht auf Abklingzeit ist (die globale Abklingzeit zählt nie). Leer = keine solche Bedingung."
L["The same enchant counting down, as it looks in play."] = "Dieselbe Verzauberung beim Herunterzählen, wie sie im Spiel aussieht."
L["The same totem counting down, as it looks in play."] = "Dasselbe Totem beim Herunterzählen, wie es im Spiel aussieht."
L["The set gate is the Set Pieces Rule on Load Conditions."] = "Das Set-Tor ist die Set-Teile-Regel unter Ladebedingungen."
L["The sets on the gear you wear now are listed; with fewer pieces on, the item goes inert."] = "Die Sets auf deiner aktuell getragenen Ausrüstung sind aufgelistet; mit weniger angelegten Teilen wird der Gegenstand inaktiv."
L["The shield is in Appearance > Icon, the color in Appearance > Fill & Colors."] = "Der Schild liegt unter Darstellung > Symbol, die Farbe unter Darstellung > Füllung & Farben."
L["The specs this skin switches on in. Pick several or Any spec."] = "Die Spezialisierungen, in denen sich dieser Skin einschaltet. Wähle mehrere oder „Beliebige Spezialisierung“."
L["The spell that puts it down. The bar follows that totem or guardian, any rank, in any slot. Empty: whatever is in the slot."] = "Der Zauber, der es aufstellt. Der Balken folgt diesem Totem oder Wächter, jedem Rang, in jedem Platz. Leer: was gerade im Platz steht."
L["The spell that puts it down. The icon follows that totem or guardian, any rank, in any slot. Empty: whatever is in the slot."] = "Der Zauber, der es aufstellt. Das Symbol folgt diesem Totem oder Wächter, jedem Rang, in jedem Platz. Leer: was gerade im Platz steht."
L["The spell that puts it down: the icon follows that totem or guardian, any rank, into whatever slot it lands."] = "Der Zauber, der es aufstellt: Das Symbol folgt diesem Totem oder Wächter, jeder Rang, in welchen Platz er auch landet."
L["The spell that puts the totem down, any rank. Empty: this icon's spell."] = "Der Zauber, der das Totem aufstellt, jeder Rang. Leer: der Zauber dieses Symbols."
L["The spell whose button or icon it rides: a spell ID, a link or the name of a spell you know. Enter applies it."] = "Der Zauber, auf dessen Taste oder Symbol es sitzt: eine Zauber-ID, ein Link oder der Name eines Zaubers, den du kennst. Enter übernimmt es."
L["The spell whose button or icon it rides: an ID, a link or a known spell's name. Several ranks may be listed. Enter applies."] = "Der Zauber, an dessen Taste oder Symbol es hängt: eine ID, ein Link oder der Name eines bekannten Zaubers. Mehrere Ränge können aufgelistet werden. Enter übernimmt."
L["The spell whose cooldown it shows. Empty: the art's spell."] = "Der Zauber, dessen Abklingzeit es zeigt. Leer: der Zauber der Grafik."
L["The spell whose icon it wears. A spell ID, a link, or the name of a spell you know."] = "Der Zauber, dessen Symbol es trägt. Eine Zauber-ID, ein Link oder der Name eines Zaubers, den du kennst."
L["The spell whose icon it wears; Appearance > Icon > Art > Custom icon wins over it. A spell ID, a link, or the name of a spell you know."] = "Der Zauber, dessen Symbol es trägt; Darstellung > Symbol > Grafik > Eigenes Symbol hat Vorrang. Eine Zauber-ID, ein Link oder der Name eines Zaubers, den du kennst."
L["The spell whose range picks the band: a melee ability for Melee, a ranged spell for Caster. Empty: your class's usual one."] = "Der Zauber, dessen Reichweite den Bereich bestimmt: eine Nahkampffähigkeit für Nahkampf, ein Fernzauber für Caster. Leer: der übliche deiner Klasse."
L["The spell whose range to your target decides the dim: an ID or a known spell's name. Empty: your class's usual one."] = "Der Zauber, dessen Reichweite zu deinem Ziel das Abdunkeln bestimmt: eine ID oder der Name eines bekannten Zaubers. Leer: der übliche deiner Klasse."
L["The spell whose range to your target decides the rule: an ID or a known spell's name. Any rank works."] = "Der Zauber, dessen Reichweite zu deinem Ziel die Regel bestimmt: eine ID oder der Name eines bekannten Zaubers. Jeder Rang funktioniert."
L["The spell's icon"] = "Das Symbol des Zaubers"
L["The spell's name or ID."] = "Name oder ID des Zaubers."
L["The spells it watches (any spell but these: the ones it skips), comma separated: IDs, links or names. Any rank."] = "Die Zauber, die es beobachtet (jeder Zauber außer diesen: die, die es überspringt), durch Kommas getrennt: IDs, Links oder Namen. Jeder Rang."
L["The spot on your screen the layout keeps its distance from when the resolution or UI scale changes."] = "Die Stelle auf deinem Bildschirm, zu der das Layout seinen Abstand hält, wenn sich Auflösung oder UI-Skalierung ändern."
L["The stack count"] = "Die Stapelzahl"
L["The stack count that fills it. 0 = the aura's most, or the custom item's Max stacks."] = "Die Stapelzahl, die es füllt. 0 = das Maximum der Aura oder die „Max. Stapel“ des eigenen Gegenstands."
L["The stacks"] = "Die Stapel"
L["The stacks climb to Max stacks, then clear: the fill and the count."] = "Die Stapel steigen bis zu den Maximalstapeln und werden dann gelöscht: die Füllung und die Anzahl."
L["The stacks climb to the maximum and drop: stack colours, the max colour and the count."] = "Die Stapel steigen bis zum Maximum und fallen: Stapelfarben, die Maximalfarbe und die Anzahl."
L["The stacks, then the timer in brackets: 3 (7.2)."] = "Die Stapel, dann der Timer in Klammern: 3 (7.2)."
L["The stance or form you are in, or one lit while you are in it."] = "Die Haltung oder Gestalt, in der du bist, oder eine, die leuchtet, solange du darin bist."
L["The stance's spell ID: one this character does not have, such as another class's."] = "Die Zauber-ID der Haltung: eine, die dieser Charakter nicht hat, z. B. die einer anderen Klasse."
L["The state that lights it: an aura up or missing, or a spell Ready, Recharging (a charge used) or On cooldown (none left)."] = "Der Zustand, der es aufleuchten lässt: eine Aura aktiv oder fehlend oder ein Zauber „Bereit“, „Lädt auf“ (eine Aufladung verbraucht) oder „Auf Abklingzeit“ (keine übrig)."
L["The swipe keeps its own opacity while Active opacity dims the icon, so only the art fades."] = "Der Wischeffekt behält seine eigene Transparenz, während die Aktiv-Transparenz das Symbol dimmt; nur die Grafik verblasst."
L["The text"] = "Der Text"
L["The text to speak is set on each trigger."] = "Der zu sprechende Text wird an jedem Auslöser festgelegt."
L["The text with a sample value, in its font, colour and box."] = "Der Text mit einem Beispielwert, in seiner Schriftart, Farbe und seinem Feld."
L["The texture"] = "Die Textur"
L["The time left"] = "Die Restzeit"
L["The time left on a weapon's enchant, with its charges."] = "Die Restzeit der Verzauberung einer Waffe, mit ihren Aufladungen."
L["The time left on one of your totems or guardians, by the spell that puts it down or by its slot."] = "Die Restzeit eines deiner Totems oder Wächter, nach dem Zauber, der es aufstellt, oder nach seinem Platz."
L["The timer"] = "Der Timer"
L["The timer is not running"] = "Der Timer läuft nicht"
L["The timer is running"] = "Der Timer läuft"
L["The timer runs"] = "Der Timer läuft"
L["The timer runs or stacks are above 0"] = "Der Timer läuft oder Stapel sind über 0"
L["The timer runs out, rests, and starts again."] = "Der Timer läuft ab, ruht und startet neu."
L["The top look wins when several hold."] = "Die oberste Optik gewinnt, wenn mehrere gelten."
L["The totem bar button this icon follows."] = "Die Totemleisten-Taste, der dieses Symbol folgt."
L["The totem or guardian slot to watch. The icon lights while anything is in it."] = "Der zu beobachtende Totem- oder Wächter-Platz. Das Symbol leuchtet, solange etwas darin ist."
L["The totem or guardian slot to watch. The icon lights while anything is in it. A shaman's slots hold: %s."] = "Der zu beobachtende Totem- oder Wächter-Platz. Das Symbol leuchtet, solange etwas darin ist. Die Plätze eines Schamanen enthalten: %s."
L["The tracked cooldown spell."] = "Der verfolgte Abklingzeit-Zauber."
L["The tracked item, or several: the icon shows the first one you carry and can use. Retargeting keeps every setting and position."] = "Der verfolgte Gegenstand oder mehrere: Das Symbol zeigt den ersten, den du dabeihast und benutzen kannst. Neu zuweisen behält jede Einstellung und Position."
L["The tracked spell. Retargeting re-keys the driver and keeps every setting and position."] = "Der verfolgte Zauber. Neu zuweisen schlüsselt den Treiber neu und behält jede Einstellung und Position."
L["The unit's name"] = "Der Name der Einheit"
L["The value counts power (45 energy, 2000 mana) instead of a percent of the bar."] = "Der Wert zählt Ressource (45 Energie, 2000 Mana) statt eines Prozentwerts des Balkens."
L["The value runs from empty to full and back: threshold colours, pips and every text follow it."] = "Der Wert läuft von leer bis voll und zurück: Schwellenfarben, Punkte und jeder Text folgen ihm."
L["The wheel"] = "Das Rad"
L["The wheel is full: empty a spot first."] = "Das Rad ist voll: Leere zuerst einen Platz."
L["The whole cooldown"] = "Die ganze Abklingzeit"
L["The whole picture"] = "Das ganze Bild"
L["Their own class and spec checks"] = "Eigene Klassen- und Spez.-Prüfungen"
L["Their own class checks"] = "Ihre eigenen Klassenprüfungen"
L["Then"] = "Dann"
L["Thick line"] = "Dicke Linie"
L["Thick outline"] = "Dicke Kontur"
L["Thin line"] = "Dünne Linie"
L["Third ammo threshold (at or below)"] = "Dritte Munitionsschwelle (bei oder unter)"
L["Third ammo threshold color"] = "Farbe der dritten Munitionsschwelle"
L["Third threshold (%)"] = "Dritte Schwelle (%)"
L["Third threshold color"] = "Farbe der dritten Schwelle"
L["This %s fails its load conditions on this character (%s). You can still edit it. Click its eye to show it on screen."] = "%s: Ladebedingungen auf diesem Charakter nicht erfüllt (%s). Bearbeiten ist trotzdem möglich. Klicke auf das Auge, um die Anzeige auf dem Bildschirm einzuschalten."
L["This bar doesn't load on this character (%s). Click its eye to show it while you edit."] = "Dieser Balken wird auf diesem Charakter nicht geladen (%s). Klicke auf sein Auge, um ihn beim Bearbeiten anzuzeigen."
L["This bar wears as many skins as it can."] = "Dieser Balken trägt so viele Skins, wie er kann."
L["This bar's aura"] = "Aura dieses Balkens"
L["This bar's name"] = "Name dieses Balkens"
L["This bar's spell"] = "Zauber dieses Balkens"
L["This character"] = "Dieser Charakter"
L["This frame stops moving with the group and goes back to where it was."] = "Dieser Frame bewegt sich nicht mehr mit der Gruppe und kehrt dorthin zurück, wo er war."
L["This group doesn't load on this character (%s). Click its eye to show it while you edit."] = "Diese Gruppe wird auf diesem Charakter nicht geladen (%s). Klicke auf ihr Auge, um sie beim Bearbeiten anzuzeigen."
L["This group follows the cursor or a nameplate. A frame can't keep up with it."] = "Diese Gruppe folgt dem Cursor oder einer Namensplakette. Ein Frame kann nicht mithalten."
L["This group holds %d icons, and they would not fit. Move one out first."] = "Diese Gruppe enthält Symbole: %d. Sie würden nicht passen. Verschiebe zuerst eines hinaus."
L["This group is not on screen, so the frame stays where it was."] = "Diese Gruppe ist nicht auf dem Bildschirm, daher bleibt der Frame, wo er war."
L["This group reminds you of it already."] = "Diese Gruppe erinnert dich bereits daran."
L["This group shows up to %d auras already."] = "Diese Gruppe zeigt bereits die Höchstzahl an Auren: %d."
L["This hero tree is not the one chosen."] = "Diese Heldentalente sind nicht die gewählten."
L["This icon doesn't load on this character (%s). Click its eye to show it while you edit."] = "Dieses Symbol wird auf diesem Charakter nicht geladen (%s). Klicke auf sein Auge, um es beim Bearbeiten anzuzeigen."
L["This icon's own rules wait until Close gaps is off: set these on the Aura Group."] = "Die eigenen Regeln dieses Symbols warten, bis „Lücken schließen“ aus ist: Lege sie in der Aura-Gruppe fest."
L["This is how Arc Auras speaks."] = "So spricht Arc Auras."
L["This item itself: not offered"] = "Dieses Element selbst: nicht angeboten"
L["This layout doesn't load on this character (%s). Click its eye to show it while you edit."] = "Dieses Layout wird auf diesem Charakter nicht geladen (%s). Klicke auf sein Auge, um es beim Bearbeiten anzuzeigen."
L["This layout stops setting these. Everything that followed it goes back to its own defaults."] = "Dieses Layout legt diese nicht mehr fest. Alles, was ihm folgte, kehrt zu seinen eigenen Standards zurück."
