L["Type order"] = "Typreihenfolge"
L["Type the aura's NAME and click a spell ID, or type IDs separated by commas or spaces. The first sets the icon's art and name."] = "Gib den NAMEN der Aura ein und klicke auf eine Zauber-ID, oder gib IDs getrennt durch Kommas oder Leerzeichen ein. Die erste bestimmt Grafik und Namen des Symbols."
L["Type the aura's NAME and click one of its spell IDs, or type the numeric ID and press Enter. A bar takes one ID. Settings are kept."] = "Gib den NAMEN der Aura ein und klicke auf eine ihrer Zauber-IDs, oder gib die numerische ID ein und drücke Enter. Ein Balken nimmt eine ID. Einstellungen bleiben erhalten."
L["Type the aura's NAME and click one of its spell IDs, or type the numeric ID. A bar takes one ID, the rank you cast."] = "Gib den NAMEN der Aura ein und klicke auf eine ihrer Zauber-IDs, oder gib die numerische ID ein. Ein Balken nimmt eine ID, den Rang, den du wirkst."
L["Type the aura's name and click one to add its ID, or type IDs separated by commas or spaces. Any of them counts."] = "Gib den Namen der Aura ein und klicke einen an, um seine ID hinzuzufügen, oder gib IDs durch Kommas oder Leerzeichen getrennt ein. Jede davon zählt."
L["Type the aura's name and click one to add its ID, or type IDs separated by commas or spaces. Any of them lights the glow."] = "Gib den Namen der Aura ein und klicke einen an, um seine ID hinzuzufügen, oder gib IDs durch Kommas oder Leerzeichen getrennt ein. Jede davon löst das Leuchten aus."
L["Type the buff's NAME to see the spell IDs that carry it, then click one (every rank comes along). Add the group version's too."] = "Gib den NAMEN des Stärkungseffekts ein, um die Zauber-IDs zu sehen, die ihn tragen, und klicke dann eine an (jeder Rang kommt mit). Füge auch die der Gruppenversion hinzu."
L["Type the spell ID"] = "Gib die Zauber-ID ein"
L["Type the spell to check."] = "Gib den zu prüfenden Zauber ein."
L["Type the spell's name and click it below, or type its ID and press Enter."] = "Gib den Namen des Zaubers ein und klicke ihn unten an, oder gib seine ID ein und drücke Enter."
L["Type the spell's name and click it below, or type its ID and press Enter. Any of the row's spells counts."] = "Gib den Namen des Zaubers ein und klicke ihn unten an, oder gib seine ID ein und drücke Enter. Jeder Zauber der Zeile zählt."
