L["What this page sets. An item's layout looks and its own values win over it; Arc's default is what it starts from."] = "Was diese Seite festlegt. Die Layout-Optiken eines Eintrags und seine eigenen Werte haben Vorrang; der Standard von Arc ist der Ausgangspunkt."
