L["When you learn a new rank, action bar buttons with the old top rank move up to it. Lower ranks and macros stay."] = "Wenn du einen neuen Rang lernst, rücken Aktionsleistentasten mit dem bisher höchsten Rang auf ihn vor. Niedrigere Ränge und Makros bleiben."
L["When you learn a new rank, your action bar buttons move up to it, out of combat."] = "Wenn du einen neuen Rang lernst, rücken deine Aktionstasten außerhalb des Kampfes darauf auf."
L["Where Position X and Y count from. Either way it moves and scales with its layout."] = "Wovon Position X und Y zählen. So oder so bewegt und skaliert es sich mit seinem Layout."
L["Where a group, icon or bar shared without its layout lands. It starts on a layout that loads on this character."] = "Wohin eine ohne ihr Layout geteilte Gruppe, ein Symbol oder ein Balken kommt. Es beginnt bei einem Layout, das auf diesem Charakter lädt."
L["Where an ability comes off cooldown: this swing, or a later one marked +1, +2."] = "Wo eine Fähigkeit von der Abklingzeit zurückkehrt: in diesem Swing oder in einem späteren, markiert mit +1, +2."
L["Where an icon goes when it shows again. Only for a single row or column."] = "Wohin ein Symbol geht, wenn es wieder erscheint. Nur für eine einzelne Zeile oder Spalte."
L["Where each item sits (its group, or free and where), its anchor, sizes, strata and mouse. Off keeps your own placement."] = "Wo jeder Eintrag sitzt (seine Gruppe oder frei und wo), sein Anker, Größen, Ebenen und Maus. Aus behält deine eigene Platzierung."
L["Where it sits: its edge against the group's."] = "Wo es sitzt: seine Kante gegen die der Gruppe."
L["Where on the group that point goes."] = "Wohin dieser Punkt an der Gruppe kommt."
L["Where the layout's center point (the cross on the map) sits from the spot it's pinned to, in whole pixels."] = "Wo der Mittelpunkt des Layouts (das Kreuz auf der Karte) von der Stelle sitzt, an der es angeheftet ist, in ganzen Pixeln."
L["Where the selection goes: free in a layout, or into a group for icons. A selected group brings its icons. Press Move or Copy to apply."] = "Wohin die Auswahl kommt: frei in ein Layout oder bei Symbolen in eine Gruppe. Eine ausgewählte Gruppe bringt ihre Symbole mit. Drücke Verschieben oder Kopieren, um es auszuführen."
L["Where they load"] = "Wo sie laden"
L["Where this sub-panel's rows go: all of this type, one layout, one group, one item, or all icons of this kind. Press Copy to apply."] = "Wohin die Zeilen dieses Unterbereichs gehen: alle dieses Typs, ein Layout, eine Gruppe, ein Eintrag oder alle Symbole dieser Art. Drücke Kopieren, um es auszuführen."
L["Where to find the pack or you, a page or a Discord. It shows as text to copy."] = "Wo man das Paket oder dich findet, eine Seite oder ein Discord. Es erscheint als Text zum Kopieren."
L["Which Casts"] = "Welche Zauber"
L["Which of the game's volume sliders its sounds come out of."] = "Über welchen der Lautstärkeregler des Spiels seine Sounds ausgegeben werden."
L["Which part of each picture stays when its edges are cropped."] = "Welcher Teil jedes Bildes bleibt, wenn seine Ränder zugeschnitten werden."
