L["While the aura is missing"] = "Solange die Aura fehlt"
L["While the aura is up"] = "Solange die Aura aktiv ist"
L["While the aura is up the game shows it over the icon: its time, and gone the moment it drops. Works in combat."] = "Solange die Aura aktiv ist, zeigt das Spiel sie über dem Symbol: ihre Zeit, und sie verschwindet im Moment des Wegfalls. Funktioniert im Kampf."
L["While the aura is up, its border takes the game's color for its type: Magic, Curse, Disease or Poison. Others keep the border color."] = "Solange die Aura aktiv ist, nimmt ihr Rahmen die Farbe des Spiels für ihren Typ an: Magie, Fluch, Krankheit oder Gift. Andere behalten die Rahmenfarbe."
L["While the aura is up, only once little time is left, only while the aura is missing, or always. Works in combat."] = "Solange die Aura aktiv ist, erst wenn wenig Zeit übrig ist, nur solange die Aura fehlt oder immer. Funktioniert im Kampf."
L["While the button is held"] = "Solange die Taste gehalten wird"
L["While the timer is idle at 0 stacks, the count shows this many: a pool reads full before its first use. Empty = off."] = "Solange der Timer bei 0 Stapeln ruht, zeigt die Anzahl so viele: Ein Vorrat wirkt vor der ersten Nutzung voll. Leer = aus."
L["While the timer runs"] = "Solange der Timer läuft"
L["While this bar is not loaded, its count stops until the next reset."] = "Solange dieser Balken nicht geladen ist, stoppt seine Zählung bis zum nächsten Zurücksetzen."
L["While this icon is not loaded, its count stops until the next reset."] = "Solange dieses Symbol nicht geladen ist, stoppt seine Zählung bis zum nächsten Zurücksetzen."
L["While this window is open a dim icon marks the spot; drag its name tab to move it."] = "Bei offenem Fenster markiert ein gedimmtes Symbol die Stelle; ziehe seinen Namens-Tab, um es zu verschieben."
L["While this window is open the outline marks the spot; drag its name tab to move it."] = "Bei offenem Fenster markiert die Kontur die Stelle; ziehe ihren Namens-Tab, um es zu verschieben."
L["While this window is open, a dim copy of the first reminder's icon marks where pulses land. On shows only the outline and name tab."] = "Bei offenem Fenster markiert eine gedimmte Kopie des Symbols der ersten Erinnerung, wo Pulse landen. „An“ zeigt nur Kontur und Namens-Tab."
L["While this window is open, each group shows its name on its top edge, which you drag it by. Off: a small green handle, name on hover."] = "Solange dieses Fenster offen ist, zeigt jede Gruppe ihren Namen am oberen Rand, an dem du sie ziehst. Aus: ein kleiner grüner Griff, Name beim Darüberfahren."
L["While this window is open, icons and bars carry a small Edit button that opens them here. Pick which kind shows it, or none."] = "Solange dieses Fenster offen ist, tragen Symbole und Balken eine kleine Taste „Bearbeiten“, die sie hier öffnet. Wähle, welche Art sie zeigt, oder keine."
L["While this window is open, items that fail their load conditions are drawn anyway, so you can place and style them."] = "Solange dieses Fenster offen ist, werden Einträge, die ihre Ladebedingungen nicht erfüllen, trotzdem gezeichnet, damit du sie platzieren und gestalten kannst."
L["While this window is open, the group you edit shows edge arrows: green adds a row or column on that side, red removes one."] = "Solange dieses Fenster offen ist, zeigt die Gruppe, die du bearbeitest, Pfeile am Rand: Grün fügt auf dieser Seite eine Zeile oder Spalte hinzu, Rot entfernt eine."
L["While toggled on"] = "Solange eingeschaltet"
L["Who carries the aura. Buffs match on friends and you, debuffs on enemies."] = "Wer die Aura trägt. Stärkungseffekte passen auf Freunde und dich, Schwächungszauber auf Feinde."
L["Who carries the aura: a buff on you, a debuff on your target, or another unit."] = "Wer die Aura trägt: ein Stärkungseffekt auf dir, ein Schwächungszauber auf deinem Ziel oder eine andere Einheit."
L["Who carries the aura: buffs on you, your pet, party and friends, debuffs on enemies. The game hides the opposite from addons."] = "Wer die Aura trägt: Stärkungseffekte auf dir, deinem Begleiter, deiner Gruppe und Freunden, Schwächungszauber auf Feinden. Das Spiel verbirgt das Gegenteil vor Addons."
L["Who carries the aura: you for a buff, your target for a debuff. You, then your target: you first. Other combinations stay dark."] = "Wer die Aura trägt: du bei einem Stärkungseffekt, dein Ziel bei einem Schwächungszauber. Du, dann dein Ziel: zuerst du. Andere Kombinationen bleiben dunkel."
L["Whole shards only"] = "Nur ganze Splitter"
L["Whose aura"] = "Wessen Aura"
L["Whose casts"] = "Wessen Zauber"
L["Wide (3:2)"] = "Breit (3:2)"
L["Width"] = "Breite"
L["Width (0 = auto)"] = "Breite (0 = auto)"
L["Windfury Totem"] = "Totem des Windzorns"
L["Windfury Weapon"] = "Waffe des Windzorns"
L["Wing Clip for melee, then Auto Shot with the 10 and 20 yard checks."] = "Zurechtstutzen für den Nahkampf, dann Automatischer Schuss mit den 10- und 20-Meter-Prüfungen."
L["Wing Clip for melee, then Auto Shot with the 20 yard check."] = "Zurechtstutzen für den Nahkampf, dann Automatischer Schuss mit der 20-Meter-Prüfung."
L["Wins over the rows below it."] = "Hat Vorrang vor den Zeilen darunter."
L["With"] = "Mit"
