L["With %s"] = "Mit %s"
L["With %s left. Click to change it."] = "Mit %s übrig. Klicke, um es zu ändern."
L["With Close gaps on, set these on the Aura Group."] = "Bei aktivem „Lücken schließen“ lege diese in der Aura-Gruppe fest."
L["With Close gaps on, the game places the row: these apply only while this window is open."] = "Bei aktivem „Lücken schließen“ platziert das Spiel die Zeile: Diese gelten nur bei offenem Fenster."
L["With a two-hander, a shield or nothing in this hand, the icon doesn't load. It comes back when you equip a weapon there."] = "Mit einer Zweihandwaffe, einem Schild oder nichts in dieser Hand lädt das Symbol nicht. Es kommt zurück, wenn du dort eine Waffe anlegst."
L["With both aura types, or on nameplates, it shows as Colors and badges."] = "Bei beiden Aura-Typen oder auf Namensplaketten wird es als „Farben und Abzeichen“ angezeigt."
L["With both, the hide list applies to the buffs only."] = "Bei beiden gilt die Ausblendliste nur für die Stärkungseffekte."
L["With both, the hide list applies to the debuffs only."] = "Bei beiden gilt die Ausblendliste nur für die Schwächungszauber."
L["With more than one row and column, a returning icon always takes its spot back."] = "Bei mehr als einer Zeile und Spalte nimmt ein zurückkehrendes Symbol immer seinen Platz zurück."
L["With no charges"] = "Ohne Aufladungen"
L["With or without a talent"] = "Mit oder ohne Talent"
L["With the bar"] = "Mit dem Balken"
L["With the look set here"] = "Mit der hier festgelegten Optik"
L["With this window open, every icon keeps its spot."] = "Bei offenem Fenster behält jedes Symbol seinen Platz."
L["With your weapon (%.2f speed)"] = "Mit deiner Waffe (Tempo %.2f)"
