L["WoW Forever"] = "WoW Forever"
L["WoW Forever: follows the rank you currently know, by name, so a new rank needs no new ID. Off: tracks the exact ID above."] = "WoW Forever: folgt dem Rang, den du gerade kennst, über den Namen, sodass ein neuer Rang keine neue ID braucht. Aus: verfolgt exakt die ID oben."
L["WoW's own option: a short tick when a spoken line ends."] = "Eigene Option von WoW: ein kurzes Ticken, wenn eine gesprochene Zeile endet."
L["WoW's own text to speech volume, so it also sets chat narration."] = "Eigene Text-to-Speech-Lautstärke von WoW, daher legt sie auch die Chat-Vorlesung fest."
L["WoW's voice"] = "Stimme von WoW"
L["WoW's voice is the one picked in WoW's own options. Male or female picks a matching voice from your system's list."] = "Die Stimme von WoW ist die in den eigenen Optionen von WoW gewählte. Männlich oder weiblich wählt eine passende Stimme aus der Liste deines Systems."
L["Wobble"] = "Wackeln"
L["Wobble (degrees)"] = "Wackeln (Grad)"
L["Words after the value. Not on a countdown the game draws (a spell's time left, an aura's)."] = "Wörter nach dem Wert. Nicht bei einem vom Spiel gezeichneten Countdown (Restzeit eines Zaubers, einer Aura)."
L["Words before the value. Not on a countdown the game draws (a spell's time left, an aura's)."] = "Wörter vor dem Wert. Nicht bei einem vom Spiel gezeichneten Countdown (Restzeit eines Zaubers, einer Aura)."
L["Words you type"] = "Wörter, die du eingibst"
L["Writes each element's name over its box, here and while you move the layout on screen."] = "Schreibt den Namen jedes Elements über sein Feld, hier und während du das Layout auf dem Bildschirm verschiebst."
