L["Your Cooldown Manager layout is ready. Turn off the game's own Cooldown Manager now?\n\nSettings > Cooldown Manager turns it back on."] = "Dein Abklingzeitmanager-Layout ist bereit. Den eigenen Abklingzeitmanager des Spiels jetzt ausschalten?\n\nEinstellungen > Abklingzeitmanager schaltet ihn wieder ein."
