L["Your Masque skins on Arc Auras icons, aura icons included: pick one per icon group in Masque."] = "Deine Masque-Skins auf Arc-Auras-Symbolen, Aura-Symbole eingeschlossen: Wähle in Masque einen pro Symbolgruppe."
