L["Your gear's item level, as each game reports it. After the name reads Name (34); under the name adds an Item Level line."] = "Die Gegenstandsstufe deiner Ausrüstung, wie sie jedes Spiel meldet. „Nach dem Namen“ ergibt Name (34); „Unter dem Namen“ fügt eine Gegenstandsstufen-Zeile hinzu."
